window.TADABBUR_YUNUS = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة يونس (١٠)، سورةٌ مكّيّةٌ في التوحيدِ والوحيِ والبعثِ وقصصِ الأنبياء (نوح، موسى، يونس). تُفتتَح بـ«الر». كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":10,"name":"يونس","total_ayahs":109,"audio":[],"passages":[{"title":"الر — آياتُ الكتابِ الحكيم، والعجبُ من الوحي","range":[1,2],"theme":"افتتاحُ السورةِ بالحروفِ المقطّعة، والردُّ على من عجب أن يُوحى إلى بشر","verses":[{"n":1,"reflection":{"text":"«الر تلك آيات الكتاب الحكيم» — افتُتحت السورةُ بـ«الر» من الحروفِ المقطّعةِ التي تنبيهًا على إعجازِ القرآنِ المؤلَّفِ من جنسِ حروفِ العرب، مع كونهم عجزوا عن معارضته؛ ثم أشار: تلك الآياتُ العاليةُ آياتُ الكتابِ المُحكَمِ المتقنِ الذي لا يأتيه الباطل، الحاكمِ بين الناس؛ فالقرآنُ كتابٌ محكمٌ حكيم؛ فعظّمه واتّبع أحكامه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحكيم"],"heart_state":{"text":"تعظيمُ القرآنِ وإجلالُ إحكامِه وحكمته."},"action":{"text":"عظّم القرآنَ في قلبك واتّبع أحكامه، فهو الكتابُ المُحكَمُ الحكيمُ الذي أعجز الخلقَ أن يأتوا بمثله."}},{"n":2,"reflection":{"text":"«أكان للناس عجبا أن أوحينا إلى رجل منهم أن أنذر الناس وبشر الذين آمنوا أن لهم قدم صدق عند ربهم قال الكافرون إن هذا لساحر مبين» — أكان عجبًا عند الناسِ أن يوحيَ الله إلى رجلٍ منهم بشرًا مثلهم ليُنذر الناسَ عذابَ الله ويبشّر المؤمنين بأنّ لهم منزلةً عاليةً ومقامَ صدقٍ عند ربّهم؟ لا عجبَ في ذلك، فهو مقتضى رحمته؛ لكنّ الكفار قالوا: إنّ هذا لساحرٌ ظاهرُ السحر! فردّوا الرحمةَ بالتكذيب؛ فالوحيُ إلى بشرٍ من جنسنا رحمةٌ لا غرابة؛ فاشكر نعمةَ الرسالة، وابشر بقدمِ الصدق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الرسالةِ، والبِشارةُ بمقامِ الصدقِ للمؤمنين."},"action":{"text":"اشكر أن أرسل الله إليك رسولًا من جنسك يهديك، واعمل صالحًا لتنال «قدمَ الصدق» عند ربّك."}}]},{"title":"الربوبيةُ والخلقُ والتدبيرُ والبعث","range":[3,6],"theme":"دلائلُ توحيدِ الربوبيةِ في الخلقِ والتدبيرِ والشمسِ والقمرِ واختلافِ الليلِ والنهار","verses":[{"n":3,"reflection":{"text":"«إن ربكم الله الذي خلق السماوات والأرض في ستة أيام ثم استوى على العرش يدبر الأمر ما من شفيع إلا من بعد إذنه ذلكم الله ربكم فاعبدوه أفلا تذكرون» — إنّ ربّكم هو الله الذي خلق السماواتِ والأرضَ في ستةِ أيامٍ (بحكمته، وهو قادرٌ على خلقها في لحظة)، ثم استوى على العرشِ استواءً يليق بجلاله، يدبّر أمرَ الكونِ كلَّه وحده، لا يشفع عنده أحدٌ إلا بإذنه؛ ذلكم العظيمُ هو الله ربّكم فاعبدوه وحده، أفلا تتذكّرون فتعتبروا؟ فمن خلق ودبّر هو المستحقُّ للعبادة؛ فأفرده بالعبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرب","المدبّر"],"heart_state":{"text":"إفرادُ الخالقِ المدبّرِ بالعبادةِ وحده."},"action":{"text":"اعبد الله وحده الذي خلق ودبّر كلَّ شيء، وتذكّر عظمتَه في خلقه فلا تصرف عبادتك لسواه."}},{"n":4,"reflection":{"text":"«إليه مرجعكم جميعا وعد الله حقا إنه يبدأ الخلق ثم يعيده ليجزي الذين آمنوا وعملوا الصالحات بالقسط والذين كفروا لهم شراب من حميم وعذاب أليم بما كانوا يكفرون» — إلى الله وحده مصيركم جميعًا يوم القيامة، وعدًا حقًّا لا خُلفَ فيه، إنه يبدأ خلقَ العبادِ ثم يعيدهم بالبعثِ ليجزيَ المؤمنين الصالحين بالعدلِ والفضل، وللكافرين شرابٌ من ماءٍ حارٍّ بالغِ الحرارةِ وعذابٌ أليمٌ بسبب كفرهم؛ فالبعثُ حقٌّ والجزاءُ عدل؛ فاستعدّ ليومِ الرجوع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ والجزاءِ، والاستعدادُ للقاءِ الله."},"action":{"text":"أيقن أنّ مرجعك إلى الله، واعمل صالحًا مستعدًّا ليومِ الجزاء، فالذي بدأ الخلقَ قادرٌ على إعادته."}},{"n":5,"reflection":{"text":"«هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب ما خلق الله ذلك إلا بالحق يفصل الآيات لقوم يعلمون» — هو الذي جعل الشمسَ ذاتَ ضياءٍ (نورٌ من ذاتها) والقمرَ ذا نورٍ (منعكسٍ)، وقدّر للقمرِ منازلَ يسير فيها لتعلموا بها عددَ السنين وحسابَ الأوقات؛ ما خلق الله ذلك عبثًا بل بالحقِّ والحكمة؛ يبيّن الآياتِ لقومٍ يعلمون فيعتبرون؛ ففي دقّةِ نظامِ الشمسِ والقمرِ آيةٌ على حكمةِ الخالق؛ فتأمّل صنعه لتعرفه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في دقّةِ خلقِ الله وحكمتِه في نظامِ الكون."},"action":{"text":"تأمّل نظامَ الشمسِ والقمرِ وحسابَ الأوقات، واستدلّ بدقّةِ صنعِ الله على حكمته وعظمته."}},{"n":6,"reflection":{"text":"«إن في اختلاف الليل والنهار وما خلق الله في السماوات والأرض لآيات لقوم يتقون» — إنّ في تعاقبِ الليلِ والنهارِ واختلافِهما طولًا وقصرًا، وفيما خلق الله في السماواتِ والأرضِ من عجائبِ المخلوقات، لأدلّةً واضحةً على وحدانيّةِ الله وقدرته، لكن ينتفع بها قومٌ يتّقون الله فيتفكّرون؛ فالتقوى تفتح بصيرةَ القلبِ لآياتِ الله؛ فاتّق الله تُبصر آياته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ التقوى تفتح القلبَ للاعتبارِ بآياتِ الله في الكون."},"action":{"text":"اتّق الله وتفكّر في آياته في الليلِ والنهارِ والخلق، فالمتّقون هم المنتفعون بالعبرة."}}]},{"title":"مصيرُ المعرِضين، ونعيمُ المؤمنين","range":[7,10],"theme":"عاقبةُ من رضي بالدنيا وغفل عن الآخرة، وجزاءُ المؤمنين وتحيّتُهم في الجنّة","verses":[{"n":7,"reflection":{"text":"«إن الذين لا يرجون لقاءنا ورضوا بالحياة الدنيا واطمأنوا بها والذين هم عن آياتنا غافلون» — إنّ الذين لا يتوقّعون البعثَ ولا يرجون ثوابَنا، ورضوا بالحياةِ الدنيا عوضًا عن الآخرةِ واطمأنّت نفوسُهم إليها فجعلوها غايةَ مطلبهم، والذين هم عن آياتِنا الكونيةِ والشرعيةِ معرضون غافلون — هؤلاء موصوفون بأسوأِ الصفات؛ فالرضا بالدنيا والغفلةُ عن الآخرةِ بابُ الخسران؛ فلا تجعل الدنيا منتهى رجائك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الرضا بالدنيا والغفلةِ عن لقاءِ الله."},"action":{"text":"لا ترضَ بالدنيا غايةً ولا تطمئن إليها وحدها، بل ارجُ لقاءَ الله واعمل له، ولا تغفل عن آياته."}},{"n":8,"reflection":{"text":"«أولئك مأواهم النار بما كانوا يكسبون» — أولئك المعرضون الراضون بالدنيا الغافلون عن الآخرة، مصيرهم النارُ ومسكنهم فيها، جزاءً بما كسبوا من الكفرِ والمعاصي والإعراض؛ فالغفلةُ عن الآخرةِ تورث دارَ البوار؛ فأيقظ قلبك من الغفلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ عاقبةِ الغفلةِ لتنبعث الهمّةُ للعمل."},"action":{"text":"أيقظ قلبك من الغفلةِ عن الآخرة، واعمل لما ينجّيك من النار، فمأوى الغافلين المعرضين النار."}},{"n":9,"reflection":{"text":"«إن الذين آمنوا وعملوا الصالحات يهديهم ربهم بإيمانهم تجري من تحتهم الأنهار في جنات النعيم» — إنّ الذين آمنوا وصدّقوا وعملوا الصالحاتِ يهديهم ربّهم بسببِ إيمانهم إلى الصراطِ المستقيمِ في الدنيا وإلى الجنّةِ في الآخرة، تجري من تحتِ منازلهم الأنهارُ في جناتِ النعيم؛ فالإيمانُ الصادقُ يورث الهدايةَ والنعيم؛ فحقّق إيمانك بالعملِ تُهدَ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الإيمانَ الصادقَ يثمر هدايةً في الدنيا ونعيمًا في الآخرة."},"action":{"text":"حقّق إيمانك بالعملِ الصالح، فالإيمانُ يهديك ربُّك به إلى الحقّ، ويورثك جناتِ النعيم."}},{"n":10,"reflection":{"text":"«دعواهم فيها سبحانك اللهم وتحيتهم فيها سلام وآخر دعواهم أن الحمد لله رب العالمين» — دعاءُ أهلِ الجنّةِ فيها تنزيهُ الله «سبحانك اللهم»، وتحيّةُ بعضهم بعضًا (وتحيّةُ الملائكةِ لهم) «سلام»، وخِتامُ دعائهم وكلامهم «الحمدُ لله ربِّ العالمين»؛ فحياتُهم كلُّها تسبيحٌ وسلامٌ وحمد، لا لغوَ فيها ولا تأثيم؛ فتعوّد لسانك بالتسبيحِ والحمدِ تكن من أهله؛ فأكثر من حمدِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحمد لله رب العالمين"],"heart_state":{"text":"تعويدُ القلبِ واللسانِ بالتسبيحِ والحمدِ والسلام."},"action":{"text":"أكثر من قول «سبحان الله» و«الحمد لله»، وأفشِ السلام، فتلك حالُ أهلِ الجنّة، فتعوّدها من الآن."}}]},{"title":"حلمُ الله، وغفلةُ الإنسانِ عند الرخاء","range":[11,14],"theme":"أنّ الله لا يعجّل العقوبة، وأنّ الإنسانَ يدعو عند الضرِّ ثم ينسى عند الكشف","verses":[{"n":11,"reflection":{"text":"«ولو يعجل الله للناس الشر استعجالهم بالخير لقضي إليهم أجلهم فنذر الذين لا يرجون لقاءنا في طغيانهم يعمهون» — لو يعجّل الله للناسِ إجابةَ دعائهم بالشرِّ عند غضبهم (كدعائهم على أنفسهم وأولادهم) كما يعجّل لهم الخيرَ الذي يستعجلونه، لأهلكهم وانتهت آجالهم؛ لكنه يمهل بحلمه، فيدع الذين لا يرجون لقاءه يتردّدون في ضلالهم وطغيانهم حائرين؛ ففي إمهالِ الله حلمٌ ورحمة؛ فاحذر أن يستدرجك الإمهال، وبادر بالتوبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ حلمِ الله في الإمهال، والحذرُ من الاغترارِ به."},"action":{"text":"احمد الله على حلمِه إذ لا يعجّل عقوبتك، ولا تغترّ بالإمهال، بل بادر بالتوبةِ قبل انقضاءِ الأجل."}},{"n":12,"reflection":{"text":"«وإذا مس الإنسان الضر دعانا لجنبه أو قاعدا أو قائما فلما كشفنا عنه ضره مر كأن لم يدعنا إلى ضر مسه كذلك زين للمسرفين ما كانوا يعملون» — وإذا أصاب الإنسانَ الضرُّ (مرضٌ أو شدّة) دعانا مضطجعًا على جنبه أو قاعدًا أو قائمًا مُلحًّا في كلِّ حال، فإذا كشفنا عنه ضرَّه أعرض ومضى كأنه لم يدعُنا يومًا لكشفِ ضرّ أصابه! كذلك زُيّن للمسرفين على أنفسهم سوءُ أعمالهم؛ فمن أقبل على الله في الشدّةِ وأعرض في الرخاءِ فقد أساء؛ فالزم ربَّك في الحالين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"دوامُ الصلةِ بالله في الرخاءِ كما في الشدّة."},"action":{"text":"الزم دعاءَ الله وشكرَه في رخائك كما تدعوه في شدّتك، ولا تكن ممّن ينسى ربَّه إذا زال ضرُّه."}},{"n":13,"reflection":{"text":"«ولقد أهلكنا القرون من قبلكم لما ظلموا وجاءتهم رسلهم بالبينات وما كانوا ليؤمنوا كذلك نجزي القوم المجرمين» — ولقد أهلكنا أممًا من قبلكم لمّا ظلموا أنفسهم بالكفرِ والتكذيب، بعد أن جاءتهم رسلُهم بالحججِ الواضحةِ فأصرّوا فلم يؤمنوا؛ مثلَ ذلك الجزاءِ نجزي المجرمين المكذّبين؛ ففي هلاكِ الأممِ عبرةٌ لمن بعدهم؛ فاتّعظ بمصارعِ الظالمين قبلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بهلاكِ الأممِ الظالمةِ المكذّبة."},"action":{"text":"اعتبر بمصيرِ الأممِ التي أهلكها الله بظلمها وتكذيبها، ولا تسلك سبيلها، فسنّةُ الله في المجرمين واحدة."}},{"n":14,"reflection":{"text":"«ثم جعلناكم خلائف في الأرض من بعدهم لننظر كيف تعملون» — ثم جعلناكم أيها الناسُ خلفاءَ في الأرضِ من بعدِ تلك الأممِ الهالكة، لنرى ونعلمَ علمَ ظهورٍ كيف تعملون: أتشكرون فتُطيعون، أم تكفرون كما فعل من قبلكم؟ فالاستخلافُ ابتلاءٌ ومسؤوليّة؛ فاعمل صالحًا فأنت مُستخلَفٌ مُختبَر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استشعارُ مسؤوليّةِ الاستخلافِ في الأرضِ أنه ابتلاء."},"action":{"text":"اعمل صالحًا مستشعرًا أنّ الله استخلفك في الأرضِ ليختبر عملك، فلا تتّبع سبيلَ من هلك قبلك."}}]},{"title":"طلبُ تبديلِ القرآن، وبراءةُ الرسولِ من التقوّل","range":[15,17],"theme":"ثباتُ الوحيِ لا يبدّله الرسول، وأنّ أظلمَ الناسِ من افترى على الله","verses":[{"n":15,"reflection":{"text":"«وإذا تتلى عليهم آياتنا بينات قال الذين لا يرجون لقاءنا ائت بقرآن غير هذا أو بدله قل ما يكون لي أن أبدله من تلقاء نفسي إن أتبع إلا ما يوحى إلي إني أخاف إن عصيت ربي عذاب يوم عظيم» — وإذا تُليت على المكذّبين آياتُنا واضحةً قال الذين لا يرجون لقاءنا: ائتِ بقرآنٍ غيرِ هذا (لا عيبَ فيه على أهوائنا) أو غيّر أحكامه! قل يا محمد: ليس لي أن أبدّله من عند نفسي، ما أتّبع إلا ما يُوحى إليّ، إني أخاف إن عصيت ربّي عذابَ يومٍ عظيم؛ فالرسولُ مبلّغٌ لا مبدّل؛ فتعظيمُ الوحيِ أن يُتّبع لا أن يُحرَّف؛ فسلّم لحكمِ الله ولا تتّبع الهوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمِ الوحيِ وعدمُ تحريفِه على الهوى."},"action":{"text":"سلّم لأحكامِ القرآنِ ولا تطلب تبديلَ ما لا يوافق هواك، فالرسولُ ما اتّبع إلا ما أوحي إليه."}},{"n":16,"reflection":{"text":"«قل لو شاء الله ما تلوته عليكم ولا أدراكم به فقد لبثت فيكم عمرا من قبله أفلا تعقلون» — قل لهم: لو شاء الله ما تلوتُ عليكم هذا القرآن ولا أعلمكم الله به، فليس من عندي؛ وقد مكثتُ فيكم عمرًا طويلًا (أربعين سنة) قبل نزوله لا أنطق بمثله ولا أدّعي علمًا، تعرفونني أمينًا صادقًا لا كاذبًا، أفلا تعقلون فتعلموا أنه من الله لا مني؟ ففي سيرةِ النبيِّ ﷺ قبل البعثةِ حجّةٌ على صدقِ وحيه؛ فتأمّل الأدلّةَ بعقلك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعمالُ العقلِ في دلائلِ صدقِ الوحي."},"action":{"text":"تأمّل بعقلك دلائلَ صدقِ القرآن: أمانةُ الرسولِ قبل البعثةِ وعجزُهم عن معارضته، فاتّبع الحقَّ بعقلٍ لا بهوى."}},{"n":17,"reflection":{"text":"«فمن أظلم ممن افترى على الله كذبا أو كذب بآياته إنه لا يفلح المجرمون» — فلا أحدَ أظلمُ ممّن اختلق على الله كذبًا فنسب إليه ما لم يقل، أو كذّب بآياته الواضحة؛ إنه لا يفوز المجرمون المفترون المكذّبون لا في الدنيا ولا في الآخرة؛ فالكذبُ على الله والتكذيبُ بآياته أعظمُ الظلم؛ فاحذر أن تقول على الله بلا علم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من القولِ على الله بلا علمٍ أو تكذيبِ آياته."},"action":{"text":"لا تقل على الله ما لا تعلم، ولا تكذّب بشيءٍ من آياته، فأظلمُ الناسِ المفتري على الله والمكذّبُ بحقّه."}}]},{"title":"بطلانُ الشفعاءِ المزعومين، ووحدةُ أصلِ الناس","range":[18,20],"theme":"إبطالُ عبادةِ ما لا ينفع بحجّةِ الشفاعة، وأنّ الغيبَ لله وحده","verses":[{"n":18,"reflection":{"text":"«ويعبدون من دون الله ما لا يضرهم ولا ينفعهم ويقولون هؤلاء شفعاؤنا عند الله قل أتنبئون الله بما لا يعلم في السماوات ولا في الأرض سبحانه وتعالى عما يشركون» — ويعبد المشركون من دون الله أصنامًا لا تملك ضرًّا ولا نفعًا، ويقولون: هؤلاء شفعاؤنا عند الله يقرّبوننا إليه! قل موبّخًا: أتخبرون الله بشريكٍ أو شفيعٍ لا يعلمه في السماواتِ ولا في الأرض (أي لا وجودَ له)؟ تنزّه الله وتعالى عمّا يشركون؛ فاتّخاذُ الوسائطِ في العبادةِ شركٌ باطل؛ فأخلص عبادتك لله وحده بلا واسطة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سبحانه وتعالى"],"heart_state":{"text":"إخلاصُ العبادةِ لله وحده وإبطالُ الوسائطِ في الدعاء."},"action":{"text":"اعبد الله وحده وادعه مباشرةً بلا واسطة، ولا تتّخذ شفيعًا تعبده دونه، فذاك عينُ الشرك."}},{"n":19,"reflection":{"text":"«وما كان الناس إلا أمة واحدة فاختلفوا ولولا كلمة سبقت من ربك لقضي بينهم فيما فيه يختلفون» — وما كان الناسُ إلا أمةً واحدةً على التوحيدِ والفطرة، ثم اختلفوا فآمن قومٌ وكفر قوم؛ ولولا كلمةٌ سبقت من ربّك بتأخيرِ الحسابِ إلى يوم القيامةِ لعُجّل الفصلُ بينهم في الدنيا فيما اختلفوا فيه؛ ففي تأخيرِ القضاءِ حكمةُ الابتلاءِ وإمهالِ التوبة؛ فاغتنم مهلةَ الحياةِ للرجوعِ إلى فطرةِ التوحيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ مهلةِ الحياةِ للثباتِ على فطرةِ التوحيد."},"action":{"text":"الزم فطرةَ التوحيدِ التي فُطر عليها الناس، واغتنم مهلةَ الحياةِ قبل يومِ الفصلِ بين المختلفين."}},{"n":20,"reflection":{"text":"«ويقولون لولا أنزل عليه آية من ربه فقل إنما الغيب لله فانتظروا إني معكم من المنتظرين» — ويقول المكذّبون: هلّا أُنزلت على محمدٍ آيةٌ حسّيّةٌ من ربّه كما نقترح! فقل لهم: إنما علمُ الغيبِ (ومنه إنزالُ الآياتِ ووقتُها) لله وحده يفعل ما يشاء بحكمته، فانتظروا قضاءَ الله فيّ وفيكم، إني معكم من المنتظرين؛ فطلبُ الآياتِ تعنّتًا لا ينفع، والأمرُ كلُّه لله؛ فسلّم الغيبَ لعالمِه، ولا تقترح على الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عالم الغيب"],"heart_state":{"text":"تسليمُ الغيبِ لله وحده، وتركُ الاقتراحِ عليه."},"action":{"text":"سلّم أمرَ الغيبِ لله وحده، ولا تعلّق إيمانك على آياتٍ تقترحها، فالإيمانُ بالحجّةِ لا بالتعنّت."}}]},{"title":"مكرُ الناسِ بعد الرحمة، وإخلاصُهم في الشدّةِ ثم بغيُهم","range":[21,23],"theme":"تقلّبُ الإنسانِ بين الشكرِ والكفر، وأنّ بغيَه يرتدُّ عليه","verses":[{"n":21,"reflection":{"text":"«وإذا أذقنا الناس رحمة من بعد ضراء مستهم إذا لهم مكر في آياتنا قل الله أسرع مكرا إن رسلنا يكتبون ما تمكرون» — وإذا أذقنا الناسَ رخاءً ونعمةً من بعدِ شدّةٍ أصابتهم، إذا هم يسارعون إلى المكرِ والاستهزاءِ والطعنِ في آياتنا بدل الشكر؛ قل: اللهُ أسرع مكرًا وأشدُّ أخذًا، إنّ ملائكتنا يكتبون كلَّ ما تمكرون فتُجازَون عليه؛ فمقابلةُ النعمةِ بالمكرِ استدراجٌ؛ فقابل نعمةَ الله بالشكرِ لا بالكفر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمةِ بعد الشدّة، والحذرُ من مكرِ الله للماكرين."},"action":{"text":"قابل نعمَ الله ورخاءه بالشكرِ والطاعة، واحذر أن تقابلها بالغفلةِ أو الطعن، فالله أسرع أخذًا."}},{"n":22,"reflection":{"text":"«هو الذي يسيركم في البر والبحر حتى إذا كنتم في الفلك وجرين بهم بريح طيبة وفرحوا بها جاءتها ريح عاصف وجاءهم الموج من كل مكان وظنوا أنهم أحيط بهم دعوا الله مخلصين له الدين لئن أنجيتنا من هذه لنكونن من الشاكرين» — هو الذي يسيّركم في البرِّ والبحر، حتى إذا ركبتم السفنَ وجرت بكم بريحٍ ليّنةٍ ففرحتم، جاءتها ريحٌ شديدةٌ وأحاط بهم الموجُ من كلِّ جهة، وأيقنوا الهلاك، دعوا الله وحده مخلصين له الدعاءَ: لئن أنجيتنا من هذه لنكوننّ من الشاكرين؛ ففي شدّةِ البحرِ يعود القلبُ إلى فطرةِ التوحيد؛ فأخلص لله في الرخاءِ كما تخلص في الشدّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجوعُ إلى إخلاصِ التوحيدِ في الشدّةِ والرخاءِ معًا."},"action":{"text":"أخلص دعاءك لله وحده دائمًا لا عند الشدّةِ فقط، وتذكّر كيف يلجأ القلبُ إليه صادقًا وقتَ الخطر."}},{"n":23,"reflection":{"text":"«فلما أنجاهم إذا هم يبغون في الأرض بغير الحق يا أيها الناس إنما بغيكم على أنفسكم متاع الحياة الدنيا ثم إلينا مرجعكم فننبئكم بما كنتم تعملون» — فلما أنجاهم الله من هولِ البحرِ نسوا عهدهم وأخذوا يفسدون في الأرضِ ويظلمون بغير حق؛ يا أيها الناسُ إنما وبالُ بغيكم راجعٌ على أنفسكم، تتمتّعون بالدنيا قليلًا ثم إلينا مصيركم فنخبركم بأعمالكم ونجازيكم؛ فالبغيُ يرتدُّ على صاحبه؛ فلا تبغِ على أحد، فعاقبةُ الظلمِ عليك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من البغيِ فإنّ عاقبتَه على صاحبه."},"action":{"text":"لا تظلم أحدًا ولا تبغِ في الأرض، واعلم أنّ وبالَ البغيِ عائدٌ عليك، ومتاعُ الدنيا زائلٌ والمرجعُ إلى الله."}}]},{"title":"مثلُ الدنيا الزائل، ودعوةُ الله إلى دارِ السلام","range":[24,25],"theme":"سرعةُ زوالِ زينةِ الدنيا، ودعوةُ الله عبادَه إلى الجنّة","verses":[{"n":24,"reflection":{"text":"«إنما مثل الحياة الدنيا كماء أنزلناه من السماء فاختلط به نبات الأرض مما يأكل الناس والأنعام حتى إذا أخذت الأرض زخرفها وازينت وظن أهلها أنهم قادرون عليها أتاها أمرنا ليلا أو نهارا فجعلناها حصيدا كأن لم تغن بالأمس كذلك نفصل الآيات لقوم يتفكرون» — إنما مثَلُ الدنيا في سرعةِ زوالها كماءٍ أنزلناه فنبت به زرعُ الأرضِ ممّا يأكل الناسُ والأنعام، حتى إذا أخذت الأرضُ زينتها وتزيّنت وظنّ أهلها أنهم مالكون لها قادرون على حصادها، جاءها أمرُنا بالهلاكِ ليلًا أو نهارًا فجعلناها محصودةً كأن لم تكن قائمةً بالأمس! كذلك نبيّن الآياتِ لقومٍ يتفكّرون؛ فالدنيا تزهو ثم تُقطف فجأة؛ فلا تغترّ بزينتها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بزينةِ الدنيا لسرعةِ زوالها."},"action":{"text":"لا تغترّ بزينةِ الدنيا وإقبالها، فقد تُقطف فجأةً كزرعٍ حُصد، واجعل قلبك معلّقًا بالباقي لا الفاني."}},{"n":25,"reflection":{"text":"«والله يدعو إلى دار السلام ويهدي من يشاء إلى صراط مستقيم» — والله يدعو عبادَه على ألسنةِ رسله إلى دارِ السلامِ (الجنّةِ، دارِ السلامةِ من كلِّ آفة)، ويوفّق من يشاء بفضله إلى الطريقِ المستقيمِ الموصلِ إليها؛ ففي مقابلِ الدنيا الزائلةِ يدعوك الله إلى دارٍ باقيةٍ سالمة؛ فأجب دعوةَ الله إلى دارِ السلام.","source":"تفسير السعدي","grade":"ma'thur"},"names":["دار السلام"],"heart_state":{"text":"إجابةُ دعوةِ الله إلى دارِ السلامِ وطلبُ الهداية."},"action":{"text":"أجب دعوةَ الله إلى الجنّةِ دارِ السلام، واسأله الهدايةَ إلى صراطه المستقيم، فهو الداعي الهادي."}}]},{"title":"جزاءُ المحسنين: الحسنى وزيادة، وجزاءُ المسيئين","range":[26,27],"theme":"أنّ للمحسنين الجنّةَ والنظرَ إلى وجهِ الله، وللمسيئين الذلَّ والظلمة","verses":[{"n":26,"reflection":{"text":"«للذين أحسنوا الحسنى وزيادة ولا يرهق وجوههم قتر ولا ذلة أولئك أصحاب الجنة هم فيها خالدون» — للذين أحسنوا الإيمانَ والعملَ الجزاءُ الحسنى (الجنّة)، وزيادةٌ عليها هي النظرُ إلى وجهِ الله الكريم (كما فسّرها النبيُّ ﷺ)، ولا يغشى وجوههم سوادٌ ولا ذلّةٌ؛ أولئك أصحابُ الجنّةِ خالدون فيها؛ فأعظمُ نعيمِ الجنّةِ النظرُ إلى وجهِ الرحمن؛ فأحسن عملك لتنال الحسنى والزيادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الحسنى وزيادة"],"heart_state":{"text":"الشوقُ إلى أعظمِ النعيم: النظرِ إلى وجهِ الله، بالإحسان."},"action":{"text":"أحسن إيمانك وعملك، فجزاءُ المحسنين الجنّةُ وزيادةٌ هي النظرُ إلى وجهِ الله، أعظمُ ما يُنال."}},{"n":27,"reflection":{"text":"«والذين كسبوا السيئات جزاء سيئة بمثلها وترهقهم ذلة ما لهم من الله من عاصم كأنما أغشيت وجوههم قطعا من الليل مظلما أولئك أصحاب النار هم فيها خالدون» — والذين كسبوا الكفرَ والسيئاتِ جزاءُ سيئتهم بمثلها عدلًا (لا يُظلمون)، وتغشاهم ذلّةٌ وهوان، ليس لهم من عذابِ الله مانعٌ يعصمهم، كأنما غُطّيت وجوههم بقطعٍ من الليلِ المظلمِ من شدّةِ سوادها وكآبتها؛ أولئك أصحابُ النارِ خالدون فيها؛ فبين نورِ وجوهِ المحسنين وظلمةِ وجوهِ المسيئين بونٌ عظيم؛ فاختر لنفسك النور.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من ظلمةِ العاقبةِ وذلِّها، واختيارُ سبيلِ النور."},"action":{"text":"احذر السيئاتِ التي تُسوّد الوجهَ وتُذلّه يوم القيامة، واسلك سبيلَ الإحسانِ لتكون من أهلِ الوجوهِ المُنيرة."}}]},{"title":"حشرُ المشركين، وتبرّؤُ الشركاءِ منهم","range":[28,30],"theme":"موقفُ القيامةِ حين يتبرّأ المعبودون، وابتلاءُ كلِّ نفسٍ بما قدّمت","verses":[{"n":28,"reflection":{"text":"«ويوم نحشرهم جميعا ثم نقول للذين أشركوا مكانكم أنتم وشركاؤكم فزيلنا بينهم وقال شركاؤهم ما كنتم إيانا تعبدون» — واذكر يومَ نحشر الخلائقَ جميعًا، ثم نقول للمشركين: الزموا مكانكم أنتم وشركاؤكم الذين عبدتموهم، فنفرّق بينهم ونقطع ما كان بينهم من صلة، ويقول الشركاءُ (المعبودون) تبرّؤًا: ما كنتم إيّانا تعبدون في الحقيقة، بل عبدتم أهواءكم! فالمعبوداتُ الباطلةُ تتبرّأ من عابديها يوم القيامة؛ فلا تعلّق قلبك بمن يخذلك يوم الحاجة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التعلّقِ بما يتبرّأ منك يومَ القيامة."},"action":{"text":"لا تعلّق قلبك ولا عبادتك بغيرِ الله، فكلُّ معبودٍ سواه يتبرّأ من عابده يوم القيامة، فأخلص لله."}},{"n":29,"reflection":{"text":"«فكفى بالله شهيدا بيننا وبينكم إن كنا عن عبادتكم لغافلين» — يقول الشركاءُ للعابدين: كفى بالله شاهدًا بيننا وبينكم أنّا كنّا عن عبادتكم إيّانا غافلين لا نشعر بها ولا نرضاها؛ فالمعبوداتُ لم تأمرهم بعبادتها ولا علمت بها؛ فلا حجّةَ للمشركِ في تقليدِ من عبد؛ فاجعل عبادتك لله وحده لا تقليدًا لأحد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ التقليدَ في الباطلِ لا ينفع، والعبادةُ توقيفٌ لله وحده."},"action":{"text":"لا تعبد الله بالتقليدِ الأعمى ولا تشرك تبعًا لغيرك، فكلٌّ يتبرّأ يوم القيامة، والعبادةُ لله وحده."}},{"n":30,"reflection":{"text":"«هنالك تبلو كل نفس ما أسلفت وردوا إلى الله مولاهم الحق وضل عنهم ما كانوا يفترون» — في ذلك الموقفِ العظيمِ تختبر كلُّ نفسٍ وتعاين ما قدّمت من عملٍ خيرًا أو شرًّا، ورُدّوا إلى الله ربّهم الحقِّ الذي يتولّى حسابهم بالعدل، وغاب عنهم واضمحلّ ما كانوا يختلقونه من آلهةٍ وشفعاء؛ فيومئذٍ يتبيّن الحقُّ من الباطل؛ فقدّم لنفسك عملًا صالحًا تجده يومَ تُبلى السرائر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ يومِ ابتلاءِ النفوسِ بما قدّمت لتقديمِ الصالح."},"action":{"text":"قدّم لنفسك اليومَ عملًا صالحًا، فكلُّ نفسٍ ستعاين ما أسلفت، ويضلّ عنها كلُّ باطلٍ اتّكلت عليه."}}]},{"title":"إقرارُهم بالرازقِ المدبّر، فهو الربُّ الحق","range":[31,33],"theme":"إلزامُ المشركين بتوحيدِ الألوهيةِ من إقرارهم بتوحيدِ الربوبية","verses":[{"n":31,"reflection":{"text":"«قل من يرزقكم من السماء والأرض أمن يملك السمع والأبصار ومن يخرج الحي من الميت ويخرج الميت من الحي ومن يدبر الأمر فسيقولون الله فقل أفلا تتقون» — قل للمشركين: من يرزقكم بالمطرِ من السماءِ وبالنباتِ من الأرض؟ ومن يملك خلقَ السمعِ والأبصارِ ونعمتَهما؟ ومن يخرج الحيَّ من الميّتِ (كالنباتِ من الحبّ) والميّتَ من الحيّ؟ ومن يدبّر أمرَ الكونِ كلَّه؟ فسيقرّون: اللهُ؛ فقل: أفلا تتّقونه فتوحّدونه؟ فمن أقرّ بأنّ الله وحده الرازقُ المدبّر لزمه أن يعبده وحده؛ فوحّد من أقررت بربوبيّته.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرزاق","المدبّر"],"heart_state":{"text":"توحيدُ العبادةِ لمن أقررتَ أنه الرازقُ المدبّر."},"action":{"text":"تأمّل أنّ الله وحده يرزقك ويدبّر أمرك ويملك سمعك وبصرك، فاعبده وحده، فمن أقرّ بربوبيّته وجب أن يفرده بالعبادة."}},{"n":32,"reflection":{"text":"«فذلكم الله ربكم الحق فماذا بعد الحق إلا الضلال فأنى تصرفون» — فذلكم الذي هذه صفاته هو الله ربّكم الحقُّ الثابتُ الذي تحقّ له العبادة، فماذا بعد الحقِّ إلا الضلالُ والباطل؟ فليس بين عبادةِ الحقِّ وعبادةِ الباطلِ منزلة؛ فكيف تُصرفون عن عبادته إلى غيره بعد وضوحِ الحقّ؟ فالحقُّ واحدٌ وما سواه ضلال؛ فالزم عبادةَ الربِّ الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الحق"],"heart_state":{"text":"لزومُ الحقِّ الواحدِ إذ ليس بعده إلا الضلال."},"action":{"text":"الزم عبادةَ الله الحقّ ولا تنحرف عنها، فما بعد الحقِّ إلا الضلال، ولا واسطةَ بينهما."}},{"n":33,"reflection":{"text":"«كذلك حقت كلمت ربك على الذين فسقوا أنهم لا يؤمنون» — كما حقّ الحقُّ ووضح، كذلك ثبتت كلمةُ ربّك وقضاؤه العدلُ على الذين خرجوا عن طاعته وأصرّوا على الفسقِ أنهم لا يؤمنون؛ لأنهم آثروا الباطلَ بعد ظهورِ الحقّ؛ فالإصرارُ على الفسقِ يُغلق بابَ الإيمان؛ فبادر بالإيمانِ ولا تصرّ على المعصية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإصرارِ على الفسقِ فيُحرَمَ العبدُ الإيمان."},"action":{"text":"بادر إلى الإيمانِ والطاعةِ ولا تصرّ على المعصية، فالإصرارُ على الفسقِ يطبع على القلبِ فلا يؤمن."}}]},{"title":"عجزُ الشركاءِ عن الخلقِ والهداية","range":[34,36],"theme":"أنّ الله وحده يبدأ الخلقَ ويهدي، وأنّ اتّباعَ الظنِّ لا يُغني","verses":[{"n":34,"reflection":{"text":"«قل هل من شركائكم من يبدأ الخلق ثم يعيده قل الله يبدأ الخلق ثم يعيده فأنى تؤفكون» — قل للمشركين: هل من آلهتكم من يبدأ خلقَ العبادِ ثم يعيدهم بعد الموت؟ لا أحد؛ قل: اللهُ وحده يبدأ الخلقَ ثم يعيده؛ فكيف تُصرفون عن عبادته إلى ما لا يخلق ولا يعيد؟ فمن انفرد بالخلقِ والإعادةِ انفرد باستحقاقِ العبادة؛ فاصرف عبادتك لمن يخلق ويعيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادةِ لتفرّده بالخلقِ والإعادة."},"action":{"text":"اعبد الله وحده الذي يبدأ الخلقَ ويعيده، ولا تلتفت إلى ما لا يخلق ولا يعيد من المعبوداتِ الباطلة."}},{"n":35,"reflection":{"text":"«قل هل من شركائكم من يهدي إلى الحق قل الله يهدي للحق أفمن يهدي إلى الحق أحق أن يتبع أمن لا يهدي إلا أن يهدى فما لكم كيف تحكمون» — قل: هل من آلهتكم من يهدي إلى الحقِّ ويرشد إليه؟ لا؛ قل: اللهُ وحده يهدي للحقّ؛ أفمن يهدي إلى الحقِّ (الله) أحقُّ أن يُتّبع ويُعبد، أم من لا يهتدي بنفسه إلا أن يُهدى ويُوجَّه (الأصنام)؟ فما لكم كيف تحكمون هذا الحكمَ الجائر؟ فالهادي إلى الحقِّ أحقُّ بالاتّباعِ من العاجزِ التابع؛ فاتّبع الهادي وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الهادي إلى الحقِّ وحده وتركُ العاجزين."},"action":{"text":"اتّبع الله وحده الهادي إلى الحقّ، فهو أحقُّ بالطاعةِ ممّا لا يهدي نفسه، فأحسن الحكمَ لعقلك."}},{"n":36,"reflection":{"text":"«وما يتبع أكثرهم إلا ظنا إن الظن لا يغني من الحق شيئا إن الله عليم بما يفعلون» — وما يتّبع أكثرُ المشركين في شركهم إلا الظنَّ والتخمينَ لا العلمَ واليقين، وإنّ الظنَّ لا يُغني عن الحقِّ شيئًا ولا يقوم مقامَ العلم؛ إنّ الله عليمٌ بما يفعلون فيجازيهم؛ فبناءُ العقيدةِ على الظنِّ ضلال؛ فاطلب في دينك اليقينَ لا الظنّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العليم"],"heart_state":{"text":"طلبُ اليقينِ في الدينِ وتركُ اتّباعِ الظنّ."},"action":{"text":"ابنِ عقيدتك على العلمِ واليقينِ من الوحي، ولا تتّبع ظنًّا ولا تقليدًا، فالظنُّ لا يُغني عن الحقِّ شيئًا."}}]},{"title":"تحدّي القرآن، وحقيقةُ تكذيبِ الجاهلين","range":[37,40],"theme":"إعجازُ القرآنِ وتحدّي المعارضة، وأنّ التكذيبَ بلا علمٍ سبيلُ الهالكين","verses":[{"n":37,"reflection":{"text":"«وما كان هذا القرآن أن يفترى من دون الله ولكن تصديق الذي بين يديه وتفصيل الكتاب لا ريب فيه من رب العالمين» — وما كان هذا القرآنُ ممّا يمكن أن يُختلَق ويُنسَب إلى الله كذبًا، فليس في قدرةِ بشرٍ أن يأتيَ بمثله، ولكنه جاء مصدّقًا لما قبله من الكتبِ السماوية، ومفصّلًا لأحكامِ الدينِ وبيانِها، لا شكَّ فيه أنه من ربِّ العالمين؛ ففي نظمِه وصدقِه وتصديقِه ما يقطع أنه وحيٌ لا افتراء؛ فأيقن أنه كلامُ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["رب العالمين"],"heart_state":{"text":"اليقينُ بأنّ القرآنَ وحيٌ من الله لا افتراءَ فيه."},"action":{"text":"أيقن أنّ القرآنَ من ربِّ العالمين لا يمكن أن يُفترى، مصدّقًا لما قبله مفصّلًا للأحكام، فاتّبعه بيقين."}},{"n":38,"reflection":{"text":"«أم يقولون افتراه قل فأتوا بسورة مثله وادعوا من استطعتم من دون الله إن كنتم صادقين» — بل أيقولون إنّ محمدًا اختلق القرآن؟ قل لهم متحدّيًا: فأتوا بسورةٍ واحدةٍ تشبهه في بلاغته ونظمه وهدايته، واستعينوا بمن استطعتم من دونِ الله (إنسًا وجنًّا) إن كنتم صادقين في دعواكم؛ فعجزُهم عن سورةٍ واحدةٍ برهانُ إعجازه؛ فتأمّل عجزَ الخلقِ عنه دليلًا على أنه من الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التدبّرُ في إعجازِ القرآنِ وعجزِ الخلقِ عن معارضته."},"action":{"text":"تأمّل التحدّي القائم: أن يأتوا بسورةٍ مثله فيعجزوا، فذاك برهانٌ قاطعٌ أنّ القرآنَ من عند الله."}},{"n":39,"reflection":{"text":"«بل كذبوا بما لم يحيطوا بعلمه ولما يأتهم تأويله كذلك كذب الذين من قبلهم فانظر كيف كان عاقبة الظالمين» — بل بادروا إلى التكذيبِ بالقرآنِ قبل أن يفهموه ويحيطوا بعلمه، وقبل أن يتبيّن لهم ما وعد به من عاقبةٍ ومآل؛ مثلَ هذا التكذيبِ العجولِ كذّب الأممُ قبلهم رسلَهم، فانظر كيف كان عاقبةُ الظالمين من الهلاك؛ فالتكذيبُ بما لم يُفهَم جهلٌ وظلم؛ فتثبّت وتعلّم قبل أن تحكم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التثبّتُ والتعلّمُ قبل الحكم، وتركُ التكذيبِ بالجهل."},"action":{"text":"لا تكذّب بما لم تُحط بعلمه، بل تثبّت وتعلّم قبل الحكم، فالتكذيبُ بالجهلِ سبيلُ الأممِ الهالكة."}},{"n":40,"reflection":{"text":"«ومنهم من يؤمن به ومنهم من لا يؤمن به وربك أعلم بالمفسدين» — ومن هؤلاء المكذّبين من سيؤمن بالقرآنِ في المستقبلِ أو من يعلم الله أنه سيؤمن، ومنهم من يموت على تكذيبه لا يؤمن به أبدًا؛ وربّك أعلم بالمفسدين المصرّين على العنادِ فيجازيهم؛ ففي الناسِ مهتدٍ ومعاند، وعلمُ العواقبِ لله؛ فابذل البلاغ، والهدايةُ بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ البلاغِ للناسِ وتفويضُ الهدايةِ إلى الله."},"action":{"text":"بلّغ الحقَّ للناسِ محتسبًا، ولا يحزنك إعراضُ المعاند، فالهدايةُ بيدِ الله وهو أعلم بالمفسدين."}}]},{"title":"البراءةُ من المكذّبين، وعجزُ الرسولِ عن قلوبِ الصمِّ العمي","range":[41,44],"theme":"أنّ الهدايةَ بيدِ الله، وأنّ الله لا يظلم الناسَ وإنما يظلمون أنفسهم","verses":[{"n":41,"reflection":{"text":"«وإن كذبوك فقل لي عملي ولكم عملكم أنتم بريئون مما أعمل وأنا بريء مما تعملون» — وإن كذّبك المشركون يا محمد بعد البيان فتبرّأ منهم وقل: لي عملي وجزاؤه، ولكم عملكم ووباله، أنتم بريئون من عملي وأنا بريءٌ من عملكم؛ فكلٌّ يحمل تبعةَ عمله؛ ففي هذا قطعُ الطمعِ في المعاندِ وإراحةُ القلبِ منه؛ فأدِّ ما عليك وابرأ من باطلِ غيرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ الواجبِ والبراءةُ من باطلِ المعاندين بلا حزن."},"action":{"text":"بلّغ الحقَّ وأدِّ عملك، وإن كُذّبت فابرأ من باطلِ المكذّبين، فكلٌّ يُجزى بعمله لا بعملِ غيره."}},{"n":42,"reflection":{"text":"«ومنهم من يستمعون إليك أفأنت تسمع الصم ولو كانوا لا يعقلون» — ومن المشركين من يستمعون إليك بآذانهم وأنت تتلو القرآن، لكنهم لا ينتفعون كالصمّ؛ أفأنت تقدر أن تُسمع الصمَّ سماعَ انتفاعٍ إذا انضمّ إلى صممهم أنهم لا يعقلون؟ فمن أغلق قلبه لا ينفعه سمعُ أذنه؛ فالعبرةُ بسمعِ القلبِ لا الأذن؛ فافتح قلبك للحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الانتفاعَ بالحقِّ بسمعِ القلبِ لا بمجرّدِ الأذن."},"action":{"text":"استمع إلى الحقِّ بقلبك لا بأذنك فقط، فمن سمع بأذنه وأغلق قلبه فهو كالأصمّ لا ينتفع."}},{"n":43,"reflection":{"text":"«ومنهم من ينظر إليك أفأنت تهدي العمي ولو كانوا لا يبصرون» — ومنهم من ينظر إليك ويرى دلائلَ نبوّتك، لكنه لا يبصر الحقَّ ببصيرته كالأعمى؛ أفأنت تقدر أن تهديَ العميَ إذا انضمّ إلى عمى أبصارهم عمى بصائرهم؟ فالهدايةُ نورٌ يقذفه الله في القلبِ لا يملكه رسول؛ فاسأل الله نورَ البصيرة؛ فالهدايةُ بيده وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ نورِ البصيرةِ من الله، فالهدايةُ بيده وحده."},"action":{"text":"اسأل الله أن يفتح بصيرتك للحقّ، فالنظرُ بالعينِ لا يكفي دون بصيرةِ القلب، والهدايةُ بيدِ الله."}},{"n":44,"reflection":{"text":"«إن الله لا يظلم الناس شيئا ولكن الناس أنفسهم يظلمون» — إنّ الله لا يظلم عبادَه شيئًا لا بزيادةِ عقوبةٍ ولا نقصِ ثواب، فهو العدلُ المطلق، ولكنّ الناسَ يظلمون أنفسهم بالكفرِ والمعاصي واختيارِ سبيلِ الهلاك؛ فما أصابهم من شرٍّ فبأيديهم؛ فلا تلم إلا نفسك على ما جنيت؛ فراجع نفسك لا القدر.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العدل"],"heart_state":{"text":"الإقرارُ بعدلِ الله، ومحاسبةُ النفسِ على التقصير."},"action":{"text":"اعلم أنّ الله لا يظلمك شيئًا، وما أصابك من سوءٍ فمن نفسك، فحاسب نفسك وأصلح عملك ولا تلم القدر."}}]},{"title":"قِصَرُ الدنيا يومَ الحشر، ورسولٌ لكلِّ أمّة","range":[45,47],"theme":"أنّ عمرَ الدنيا كساعة، وأنّ القضاءَ بالقسطِ بعد بلوغِ الرسالة","verses":[{"n":45,"reflection":{"text":"«ويوم يحشرهم كأن لم يلبثوا إلا ساعة من النهار يتعارفون بينهم قد خسر الذين كذبوا بلقاء الله وما كانوا مهتدين» — ويوم يحشر الله الخلائق يستقصرون مدّةَ لبثهم في الدنيا حتى كأنهم لم يمكثوا إلا ساعةً من نهار، يتعارفون بينهم ثم ينقطع التعارف؛ قد خسر الذين كذّبوا بلقاءِ الله وما كانوا مهتدين إلى الحقّ؛ فالدنيا مهما طالت قصيرةٌ في جنبِ الآخرة؛ فلا تبع الأبديَّ بالساعةِ العابرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ قِصَرِ الدنيا لئلا يُباعَ بها النعيمُ الدائم."},"action":{"text":"تذكّر أنّ عمرك في الدنيا كساعةٍ ستقصر يوم الحشر، فلا تبع آخرتك الباقيةَ بدنيا عابرة."}},{"n":46,"reflection":{"text":"«وإما نرينك بعض الذي نعدهم أو نتوفينك فإلينا مرجعهم ثم الله شهيد على ما يفعلون» — وإمّا نُرينّك في حياتك بعضَ ما نعد المكذّبين من العذاب، أو نتوفّينّك قبل ذلك، فإلينا مرجعهم على كلِّ حال، ثم الله شاهدٌ على أعمالهم فيجازيهم؛ فسواءٌ عُجّل العقابُ أو أُخّر فالمآلُ إلى الله؛ فلا يستبطئنّك تأخيرُ الجزاء، فالحسابُ آتٍ لا محالة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الشهيد"],"heart_state":{"text":"الصبرُ وتفويضُ أمرِ الجزاءِ إلى الله شهيدِ الأعمال."},"action":{"text":"اصبر ولا يستبطئك تأخّرُ جزاءِ الظالمين، فمرجعهم إلى الله وهو شهيدٌ على أعمالهم يجازيهم."}},{"n":47,"reflection":{"text":"«ولكل أمة رسول فإذا جاء رسولهم قضي بينهم بالقسط وهم لا يظلمون» — ولكلِّ أمةٍ من الأممِ رسولٌ يبلّغهم أمرَ الله، فإذا جاءهم رسولُهم فبلّغ وكذّبوه قُضي بينهم بالعدلِ فنُجّي المؤمنُ وأُهلك المكذّب، وهم لا يُظلمون بزيادةِ عقوبةٍ ولا نقص؛ ففي إرسالِ الرسلِ إقامةُ الحجّةِ قبل الجزاء؛ فاشكر نعمةَ بلوغِ الرسالةِ إليك، واتّبع رسولك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الرسالةِ، والاعتبارُ بعدلِ الله في الأمم."},"action":{"text":"اشكر أن بلغتك رسالةُ نبيّك ﷺ واتّبعه، فالحجّةُ قامت، والقضاءُ بين الأممِ بالعدلِ بعد البلاغ."}}]},{"title":"استعجالُ العذاب، وأنّ الآجالَ بيدِ الله","range":[48,52],"theme":"استهزاءُ المكذّبين بالوعيد، وأنّ العذابَ إذا وقع لا ينفع الإيمان","verses":[{"n":48,"reflection":{"text":"«ويقولون متى هذا الوعد إن كنتم صادقين» — ويقول المكذّبون استهزاءً واستبعادًا للبعثِ والعذاب: متى يقع هذا الوعدُ الذي تعدوننا به إن كنتم صادقين؟ فيستعجلون ما يضرّهم جهلًا وعنادًا؛ فاستعجالُ الوعيدِ حمقٌ وغفلة؛ فلا تستبطئ وعدَ الله ولا تستهزئ به، بل استعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بوعيدِ الله واستبعادِه."},"action":{"text":"لا تستبطئ وعدَ الله ولا تستهزئ بالوعيد، بل خذ حذرك واستعدّ للقاءِ الله قبل فواتِ الأوان."}},{"n":49,"reflection":{"text":"«قل لا أملك لنفسي ضرا ولا نفعا إلا ما شاء الله لكل أمة أجل إذا جاء أجلهم فلا يستأخرون ساعة ولا يستقدمون» — قل يا محمد: لا أملك لنفسي جلبَ نفعٍ ولا دفعَ ضرٍّ إلا بمشيئةِ الله، فكيف أملك تعجيلَ عذابكم؟ لكلِّ أمةٍ أجلٌ محدودٌ لهلاكها، إذا جاء أجلهم لا يتأخّرون عنه لحظةً ولا يتقدّمون؛ فالآجالُ بيدِ الله وحده؛ فسلّم أمرك لمقدّرِ الآجال، ولا تستعجل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوكّلُ على الله وحده مالكِ النفعِ والضرِّ والآجال."},"action":{"text":"علّق أمرك بالله وحده، فهو مالكُ النفعِ والضرِّ ومقدّرُ الآجال، ولا يملك أحدٌ لنفسه ولا لغيره شيئًا إلا بمشيئته."}},{"n":50,"reflection":{"text":"«قل أرأيتم إن أتاكم عذابه بياتا أو نهارا ماذا يستعجل منه المجرمون» — قل لهم: أخبروني إن جاءكم عذابُ الله ليلًا وأنتم نائمون أو نهارًا وأنتم في شغلكم، أيَّ شيءٍ من هذا العذابِ يستعجل المجرمون؟ فليس فيه ما يُستعجَل، بل كلُّه هولٌ ونكال؛ فاستعجالُ العذابِ حمقٌ لا يدري صاحبُه ما يطلب؛ فبادر بالتوبةِ قبل أن يبغتك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من بغتةِ العذابِ ليلًا أو نهارًا، والمبادرةُ بالتوبة."},"action":{"text":"لا تأمن أن يأتيك أمرُ الله بغتةً ليلًا أو نهارًا، فبادر بالتوبةِ والاستعدادِ ولا تستعجل ما لا خيرَ فيه."}},{"n":51,"reflection":{"text":"«أثم إذا ما وقع آمنتم به آلآن وقد كنتم به تستعجلون» — أثم إذا وقع العذابُ الذي كنتم تستعجلونه آمنتم به حين لا ينفع الإيمان؟ فيُقال لهم توبيخًا: آلآن تؤمنون وقد كنتم به تستعجلون مستهزئين؟ فالإيمانُ عند معاينةِ العذابِ لا يُقبل؛ فبادر بالإيمانِ في زمنِ المهلةِ قبل أن يُغلَق بابُه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ في زمنِ المهلةِ قبل فواته."},"action":{"text":"آمن واعمل الآن في زمنِ المهلة، فالإيمانُ عند معاينةِ العذابِ لا ينفع، ولا تؤخّر توبتك إلى فواتِ الأوان."}},{"n":52,"reflection":{"text":"«ثم قيل للذين ظلموا ذوقوا عذاب الخلد هل تجزون إلا بما كنتم تكسبون» — ثم يُقال للذين ظلموا أنفسهم بالكفر: ذوقوا عذابَ الخلدِ الدائمِ الذي لا انقطاع له، هل تُجزَون إلا بمثلِ ما كسبتم من الكفرِ والمعاصي؟ فالجزاءُ من جنسِ العمل، وعذابُ الخلدِ ثمرةُ الكفرِ الدائم؛ فاحذر عملًا تُخلَّد بسببه في النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من عذابِ الخلدِ ثمرةِ الكفرِ والظلم."},"action":{"text":"احذر أعمالَ الكفرِ والظلمِ التي جزاؤها عذابُ الخلد، واعلم أنك لا تُجزى إلا بما كسبت، فأحسن كسبك."}}]},{"title":"تأكيدُ صدقِ الوعيد، ومُلكُ الله وإحياؤه","range":[53,56],"theme":"القسمُ على حقّيّةِ البعث، وأنّ لله ملكَ كلِّ شيءٍ وأنّ وعده حق","verses":[{"n":53,"reflection":{"text":"«ويستنبئونك أحق هو قل إي وربي إنه لحق وما أنتم بمعجزين» — ويستخبرونك مستبعدين: أحقٌّ هذا الوعدُ بالبعثِ والعذاب؟ قل مؤكّدًا بالقسم: إي وربّي إنه لحقٌّ لا شكَّ فيه، وما أنتم بفائتين اللهَ ولا معجزيه هربًا؛ ففي القسمِ على البعثِ تأكيدٌ لليقين؛ فأيقن بلقاءِ الله يقينًا لا يخالطه شك، واستعدّ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ الجازمُ بحقّيّةِ البعثِ والجزاء."},"action":{"text":"أيقن أنّ البعثَ حقٌّ لا ريبَ فيه كما أقسم الله عليه، واستعدّ للقائه، فلن تُعجزه ولن تفوته."}},{"n":54,"reflection":{"text":"«ولو أن لكل نفس ظلمت ما في الأرض لافتدت به وأسروا الندامة لما رأوا العذاب وقضي بينهم بالقسط وهم لا يظلمون» — ولو أنّ لكلِّ نفسٍ كافرةٍ ظلمت مِلءَ الأرضِ ذهبًا لبذلته فداءً لنفسها من العذابِ يوم القيامة، ولن يُقبل؛ وأخفوا الندامةَ في قلوبهم لمّا عاينوا العذاب، وقُضي بينهم بالعدل، وهم لا يُظلمون؛ فيوم القيامةِ لا فديةَ ولا محاباة؛ فقدّم الفديةَ اليوم بالإيمانِ والعملِ قبل يومِ لا ينفع فيه مال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقديمُ العملِ الصالحِ اليومَ إذ لا فديةَ يومَ القيامة."},"action":{"text":"افتدِ نفسك اليومَ بالإيمانِ والعملِ الصالح، فيوم القيامةِ لا يُقبل فداءٌ ولو مِلءَ الأرضِ ذهبًا."}},{"n":55,"reflection":{"text":"«ألا إن لله ما في السماوات والأرض ألا إن وعد الله حق ولكن أكثرهم لا يعلمون» — ألا فلينتبه الغافلون: إنّ لله وحده ملكَ ما في السماواتِ والأرضِ خلقًا وتصرّفًا، ألا إنّ وعدَ الله بالبعثِ والجزاءِ حقٌّ واقعٌ لا محالة، ولكنّ أكثرَ الناسِ لا يعلمون ذلك لغفلتهم؛ فمن أيقن بمُلكِ الله وصدقِ وعده استقام؛ فاعلم أنّ وعدَ الله حقٌّ واعمل بمقتضاه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بمُلكِ الله وصدقِ وعده يورث الاستقامة."},"action":{"text":"أيقن أنّ لله ملكَ كلِّ شيء، وأنّ وعدَه حقٌّ آتٍ، واعمل بمقتضى هذا اليقين، ولا تكن من الغافلين."}},{"n":56,"reflection":{"text":"«هو يحيي ويميت وإليه ترجعون» — هو الله وحده يحيي الخلقَ من العدمِ ويميتهم عند انقضاءِ آجالهم، ثم يعيدهم بالبعث، وإليه وحده ترجعون للحسابِ والجزاء؛ فمن بيده الإحياءُ والإماتةُ والمرجعُ هو المستحقُّ للعبادةِ والخوف؛ فاستعدّ لرجوعك إلى من يحيي ويميت.","source":"تفسير السعدي","grade":"ma'thur"},"names":["المحيي","المميت"],"heart_state":{"text":"استحضارُ الرجوعِ إلى الله المحيي المميت."},"action":{"text":"تذكّر أنّ الله يحييك ويميتك وإليه ترجع، فاعمل لهذا الرجوع، ولا تعلّق قلبك بغيرِ من بيده حياتك وموتك."}}]},{"title":"القرآنُ موعظةٌ وشفاء، والفرحُ بفضلِ الله","range":[57,58],"theme":"أنّ القرآنَ شفاءُ القلوبِ وهدًى ورحمة، وأنّ الفرحَ الحقَّ به لا بالمال","verses":[{"n":57,"reflection":{"text":"«يا أيها الناس قد جاءتكم موعظة من ربكم وشفاء لما في الصدور وهدى ورحمة للمؤمنين» — يا أيها الناسُ قد جاءكم القرآنُ من ربّكم: موعظةٌ تزجر عن القبائحِ وترغّب في الخير، وشفاءٌ لما في الصدورِ من أمراضِ الشكِّ والشبهاتِ والشهواتِ والنفاق، وهدًى من الضلال، ورحمةٌ لمن آمن به وعمل به؛ فالقرآنُ دواءُ القلبِ ونورُه؛ فاطلب شفاءَ قلبك وهدايتَه في القرآنِ تدبّرًا وعملًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["موعظة","شفاء","هدى","رحمة"],"heart_state":{"text":"طلبُ شفاءِ القلبِ وهدايتِه في القرآنِ تدبّرًا وعملًا."},"action":{"text":"اجعل القرآنَ موعظتك وشفاءَ صدرك وهُداك: تدبّره واعمل به، فهو دواءُ أمراضِ القلبِ ونورُ الهداية."}},{"n":58,"reflection":{"text":"«قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون» — قل للناس: بفضلِ الله (الإسلامِ والإيمان) وبرحمته (القرآنِ والهداية) فبذلك وحده فليفرحوا فرحَ سرورٍ وشكر، فهو خيرٌ ممّا يجمعون من حطامِ الدنيا الزائل؛ ففرحُ القلبِ الحقُّ بنعمةِ الدينِ لا بالمال؛ فليكن فرحك بالهدى والقرآنِ أعظمَ من فرحك بالدنيا.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فضل الله","رحمته"],"heart_state":{"text":"أن يكون الفرحُ الأكبرُ بنعمةِ الدينِ والقرآنِ لا بالمال."},"action":{"text":"افرح بنعمةِ الإيمانِ والقرآنِ والهداية أعظمَ من فرحك بمالٍ أو متاع، فذلك خيرٌ ممّا يجمع الناس."}}]},{"title":"التحليلُ والتحريمُ حقُّ الله، وخطرُ الافتراءِ عليه","range":[59,60],"theme":"إنكارُ تشريعِ العبادِ بلا إذنٍ من الله، وسوءُ مصيرِ المفترين","verses":[{"n":59,"reflection":{"text":"«قل أرأيتم ما أنزل الله لكم من رزق فجعلتم منه حراما وحلالا قل آلله أذن لكم أم على الله تفترون» — قل للمشركين الذين حرّموا على أنفسهم ما أحلّ الله (كالبحيرةِ والسائبة): أخبروني عمّا رزقكم الله من الطيّبات، بأيِّ حقٍّ جعلتم بعضه حرامًا وبعضه حلالًا من عند أنفسكم؟ قل: آللهُ أذن لكم بهذا التشريع، أم على الله تكذبون بنسبته إليه؟ فالتحليلُ والتحريمُ حقٌّ لله وحده؛ فلا تحرّم ولا تُحلّ إلا بما شرع الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ التشريعَ (التحليلَ والتحريمَ) حقٌّ لله وحده."},"action":{"text":"لا تُحلّل ولا تحرّم شيئًا إلا بدليلٍ من شرعِ الله، فالتشريعُ حقُّه وحده، ونسبةُ التحريمِ إليه بلا إذنٍ افتراء."}},{"n":60,"reflection":{"text":"«وما ظن الذين يفترون على الله الكذب يوم القيامة إن الله لذو فضل على الناس ولكن أكثرهم لا يشكرون» — وأيُّ ظنٍّ يظنّه الذين يختلقون على الله الكذبَ بما يصيبهم يوم القيامة؟ أيظنّون أنه يغفر لهم بلا توبة؟ إنّ الله لذو فضلٍ عظيمٍ على الناسِ بالنعمِ الظاهرةِ والباطنة، ولكنّ أكثرهم لا يشكرون فضله بل يقابلونه بالافتراءِ والكفر؛ فقابل فضلَ الله بالشكرِ لا بالكذبِ عليه؛ فاشكر تزد.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ذو فضل"],"heart_state":{"text":"شكرُ فضلِ الله الواسع، والحذرُ من الكذبِ عليه."},"action":{"text":"اشكر فضلَ الله عليك بالنعمِ الكثيرة، واحذر أن تقابله بالافتراءِ عليه أو جحودِ نعمته، فأكثرُ الناسِ لا يشكرون."}}]},{"title":"شهودُ الله على كلِّ شأن، وإحاطةُ علمِه بمثقالِ الذرّة","range":[61,61],"theme":"مراقبةُ الله للعبدِ في كلِّ حالٍ، وإحاطةُ علمِه بأدقِّ الأشياء","verses":[{"n":61,"reflection":{"text":"«وما تكون في شأن وما تتلو منه من قرآن ولا تعملون من عمل إلا كنا عليكم شهودا إذ تفيضون فيه وما يعزب عن ربك من مثقال ذرة في الأرض ولا في السماء ولا أصغر من ذلك ولا أكبر إلا في كتاب مبين» — وما تكون يا محمد في حالٍ من أحوالك، وما تتلو من القرآن، ولا تعملون أيها الناسُ عملًا، إلا وكنّا عليكم شهودًا حاضرين مطّلعين حين تخوضون فيه؛ ولا يغيب عن علمِ ربّك مقدارُ ذرّةٍ في الأرضِ ولا في السماء، ولا أصغرُ من الذرّةِ ولا أكبرُ إلا وهو مثبتٌ في كتابٍ مبين (اللوحِ المحفوظ)؛ فأنت في كلِّ لحظةٍ بمرأى الله؛ فراقبه في سرّك وعلنك، وأتقن عملك فهو يراه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الشهيد","المحيط علمًا"],"heart_state":{"text":"مراقبةُ الله الدائمةُ في كلِّ عملٍ وقولٍ وحال."},"action":{"text":"استحضر أنّ الله شاهدٌ عليك في كلِّ شأنٍ وعمل، لا يعزب عنه مثقالُ ذرّة، فأتقن عملك وراقبه في السرِّ والعلن."}}]},{"title":"أولياءُ الله: لا خوفٌ ولا حزن","range":[62,64],"theme":"صفةُ أولياءِ الله (الإيمانُ والتقوى)، وبشراهم في الدارين","verses":[{"n":62,"reflection":{"text":"«ألا إن أولياء الله لا خوف عليهم ولا هم يحزنون» — ألا فليُعلَم: إنّ أولياءَ الله (أحبّاءه المقرّبين إليه بالطاعة) لا خوفٌ عليهم فيما يستقبلون من أهوالِ الآخرة، ولا هم يحزنون على ما فاتهم من الدنيا أو خلّفوا؛ فبولايةِ الله يزول الخوفُ والحزن؛ فاطلب ولايةَ الله بالإيمانِ والتقوى تنل أمنَه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ ولايةِ الله التي تُذهب الخوفَ والحزن."},"action":{"text":"اطلب أن تكون من أولياءِ الله بالإيمانِ والتقوى، فولايتُه تورث القلبَ أمنًا من الخوفِ والحزن."}},{"n":63,"reflection":{"text":"«الذين آمنوا وكانوا يتقون» — هؤلاء الأولياءُ هم الذين جمعوا بين الإيمانِ الصادقِ بالله وملائكتِه وكتبِه ورسله، وبين التقوى بامتثالِ الأوامرِ واجتنابِ النواهي؛ فالولايةُ ليست دعوى بل إيمانٌ وتقوى؛ فليست الولايةُ بالأماني، بل بالإيمانِ والعمل؛ فحقّق الوصفين تكن وليًّا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["أولياء الله"],"heart_state":{"text":"أنّ ولايةَ الله تُنال بالإيمانِ والتقوى لا بالدعوى."},"action":{"text":"حقّق الإيمانَ بالتصديقِ والتقوى بالعمل، فبهما تُنال ولايةُ الله، لا بالأماني والدعاوى."}},{"n":64,"reflection":{"text":"«لهم البشرى في الحياة الدنيا وفي الآخرة لا تبديل لكلمات الله ذلك هو الفوز العظيم» — لأولياءِ الله البشرى في الحياةِ الدنيا بالرؤيا الصالحةِ يراها المؤمنُ أو تُرى له، وبالثناءِ الحسنِ، وبالطمأنينة؛ وفي الآخرةِ بالجنّةِ ورضوانِ الله؛ لا تبديلَ لوعدِ الله ولا خُلفَ فيه؛ ذلك هو الفوزُ العظيمُ الذي لا فوزَ بعده؛ فبشرى الله لأوليائه حقٌّ لا يتبدّل؛ فاعمل لتكون منهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["البشرى"],"heart_state":{"text":"الرجاءُ في بشرى الله لأوليائه في الدارين."},"action":{"text":"اعمل لتنال بشرى الله لأوليائه في الدنيا (الطمأنينةِ والرؤيا الصالحة) والآخرةِ (الجنّة)، فوعدُه لا يتبدّل."}}]},{"title":"العزّةُ لله، ومُلكُه، وآيةُ الليلِ والنهار","range":[65,67],"theme":"تسليةُ النبيِّ بأنّ العزّةَ لله جميعًا، ودلائلُ توحيدِه في الكون","verses":[{"n":65,"reflection":{"text":"«ولا يحزنك قولهم إن العزة لله جميعا هو السميع العليم» — ولا يحزنك يا محمد ما يقوله المكذّبون من الطعنِ والاستهزاء، فإنّ العزّةَ والغلبةَ لله جميعًا يؤتيها من يشاء وينصر أولياءه، وهو السميعُ لأقوالهم العليمُ بأحوالهم فيجازيهم؛ فمن كانت العزّةُ لربّه فلا يحزنه كلامُ الخلق؛ فاطلب العزّةَ من الله وحده، ولا يهنك قولُ الطاعنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السميع","العليم","العزيز"],"heart_state":{"text":"طلبُ العزّةِ من الله وحده، وعدمُ الحزنِ لقولِ الخلق."},"action":{"text":"لا تحزن لكلامِ من يطعن في الحقّ، واطلب العزّةَ من الله وحده، فالعزّةُ كلُّها له وهو سميعٌ عليم."}},{"n":66,"reflection":{"text":"«ألا إن لله من في السماوات ومن في الأرض وما يتبع الذين يدعون من دون الله شركاء إن يتبعون إلا الظن وإن هم إلا يخرصون» — ألا إنّ لله وحده ملكَ كلِّ من في السماواتِ والأرضِ عبيدًا مربوبين، فكيف يُتّخذ بعضُهم شريكًا؟ وما يتّبع المشركون في دعائهم شركاءَ من دون الله حقيقةً، إن يتّبعون إلا الظنَّ الباطل، وما هم إلا يكذبون ويحدسون؛ فعبادةُ غيرِ الله بناءٌ على ظنٍّ وتخمين؛ فاعبد المالكَ وحده، ولا تتّبع ظنًّا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ المالكِ بالعبادةِ، وتركُ اتّباعِ الظنِّ في الدين."},"action":{"text":"اعبد الله وحده الذي يملك كلَّ من في الكون، ولا تتّبع في دينك ظنًّا أو تخمينًا، فعبادةُ سواه ظنٌّ باطل."}},{"n":67,"reflection":{"text":"«هو الذي جعل لكم الليل لتسكنوا فيه والنهار مبصرا إن في ذلك لآيات لقوم يسمعون» — هو الذي جعل لكم الليلَ مظلمًا لتسكنوا فيه وتستريحوا من عناءِ النهار، وجعل النهارَ مضيئًا تبصرون فيه لتبتغوا من فضلِ الله؛ إنّ في هذا التدبيرِ لآياتٍ على وحدانيّةِ الله ورحمته لقومٍ يسمعون سماعَ تدبّرٍ وقبول؛ ففي تعاقبِ السكونِ والحركةِ نعمةٌ وآية؛ فتأمّل نعمةَ الليلِ والنهارِ واشكرها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في نعمةِ الليلِ والنهارِ وشكرُها."},"action":{"text":"تأمّل نعمةَ الله في الليلِ للسكونِ والنهارِ للسعي، واشكرها، واجعل ليلك سكنًا ونهارك عملًا صالحًا."}}]},{"title":"تنزيهُ الله عن الولد، وخسارةُ المفترين","range":[68,70],"theme":"إبطالُ دعوى الولدِ لله، وأنّ متاعَ المفترين قليلٌ يعقبه عذاب","verses":[{"n":68,"reflection":{"text":"«قالوا اتخذ الله ولدا سبحانه هو الغني له ما في السماوات وما في الأرض إن عندكم من سلطان بهذا أتقولون على الله ما لا تعلمون» — قال المفترون: اتّخذ الله ولدًا! تنزّه الله عن ذلك، هو الغنيُّ عن كلِّ شيءٍ فلا يحتاج إلى ولد، له ما في السماواتِ وما في الأرضِ ملكًا وعبيدًا، فكيف يكون بعضُ ملكه ولدًا له؟ ليس عندكم حجّةٌ ولا برهانٌ بهذا القول، أتقولون على الله ما لا تعلمون؟ فنسبةُ الولدِ إلى الله أعظمُ الفريةِ وأبطلُها؛ فنزّه الله عن كلِّ نقص.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغني","سبحانه"],"heart_state":{"text":"تنزيهُ الله عن الولدِ والنقص، وإجلالُ غناه."},"action":{"text":"نزّه الله عن الولدِ والشريكِ وكلِّ نقص، واعلم أنه الغنيُّ المالكُ لكلِّ شيء، ولا تقل عليه ما لا تعلم."}},{"n":69,"reflection":{"text":"«قل إن الذين يفترون على الله الكذب لا يفلحون» — قل يا محمد: إنّ الذين يختلقون على الله الكذبَ (بنسبةِ الولدِ أو الشريكِ أو تحريمِ الحلال) لا يفوزون بمطلوبٍ ولا ينجون من مرهوبٍ، لا في الدنيا ولا في الآخرة؛ فالافتراءُ على الله سببُ الخسرانِ المحقّق؛ فاحذر الكذبَ عليه، فالمفتري لا يفلح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الافتراءِ على الله، فالمفتري لا يفلح."},"action":{"text":"احذر أن تنسب إلى الله ما لم يقله، فالمفترون عليه لا يفلحون أبدًا، فتحرّ الصدقَ فيما تنسبه إلى الدين."}},{"n":70,"reflection":{"text":"«متاع في الدنيا ثم إلينا مرجعهم ثم نذيقهم العذاب الشديد بما كانوا يكفرون» — لهؤلاء المفترين متاعٌ قليلٌ زائلٌ في الدنيا يتقلّبون فيه، ثم إلينا مصيرهم بالموتِ والبعث، ثم نذيقهم العذابَ الشديدَ الدائمَ بسببِ كفرهم وافترائهم؛ فمتاعُ الكفرِ ساعةٌ يعقبها عذابٌ طويل؛ فلا يغرّنّك ما هم فيه من إمهالٍ ومتاع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا يغترَّ القلبُ بمتاعِ المفترين فعاقبتُه العذاب."},"action":{"text":"لا تغترّ بما في المفترين والكفارِ من متاعٍ زائل، فهو قليلٌ يعقبه عذابٌ شديد، والعاقبةُ للمتّقين."}}]},{"title":"نبأُ نوحٍ مع قومه — ثباتُ الداعيةِ ونجاةُ المؤمنين","range":[71,73],"theme":"توكّلُ نوحٍ على الله وتحدّيه لقومه، ونجاتُه وإغراقُ المكذّبين","verses":[{"n":71,"reflection":{"text":"«واتل عليهم نبأ نوح إذ قال لقومه يا قوم إن كان كبر عليكم مقامي وتذكيري بآيات الله فعلى الله توكلت فأجمعوا أمركم وشركاءكم ثم لا يكن أمركم عليكم غمة ثم اقضوا إلي ولا تنظرون» — واتل يا محمد على قومك خبرَ نوحٍ إذ قال لقومه: يا قوم إن كان عظُم عليكم مُقامي بينكم وتذكيري لكم بآياتِ الله وثقُل ذلك، فعلى الله وحده توكّلت لا أبالي بكم، فاعزموا أمركم أنتم وشركاؤكم على ما تريدون بي، ثم لا يكن أمركم عليكم مستورًا مبهمًا بل أظهروه، ثم أنفذوا فيّ ما عزمتم ولا تمهلوني؛ ففي توكّلِ نوحٍ وتحدّيه غايةُ الثقةِ بالله؛ فتوكّل على الله في الحقِّ ولا تهب كثرةَ المخالفين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوكّلُ على الله والثباتُ على الحقِّ ولو خالف الجميع."},"action":{"text":"توكّل على الله في دعوتك للحقّ، واثبت ولو اجتمع عليك المخالفون، كما تحدّى نوحٌ قومَه ثقةً بربّه."}},{"n":72,"reflection":{"text":"«فإن توليتم فما سألتكم من أجر إن أجري إلا على الله وأمرت أن أكون من المسلمين» — فإن أعرضتم عن دعوتي فلا يضرّني، فما طلبت منكم على تبليغِ الرسالةِ أجرًا حتى تتّهموني، ما ثوابي إلا على الله وحده، وأُمرت أن أكون من المستسلمين لأمرِ الله المنقادين له؛ ففي تجرّدِ الداعيةِ عن الأجرِ قوّةٌ لدعوته؛ فادعُ إلى الله محتسبًا أجرك عليه وحده، مستسلمًا لأمره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ في الدعوةِ واحتسابُ الأجرِ على الله وحده."},"action":{"text":"ادعُ إلى الحقِّ لا تبتغي عليه أجرًا من الناس، محتسبًا ثوابك على الله، مستسلمًا لأمره كما فعل نوح."}},{"n":73,"reflection":{"text":"«فكذبوه فنجيناه ومن معه في الفلك وجعلناهم خلائف وأغرقنا الذين كذبوا بآياتنا فانظر كيف كان عاقبة المنذرين» — فكذّب قومُ نوحٍ رسولَهم، فنجّيناه ومن آمن معه في السفينة، وجعلناهم خلفاءَ في الأرضِ يعمرونها بعد الهالكين، وأغرقنا الذين كذّبوا بآياتنا؛ فانظر يا محمد كيف كان عاقبةُ الذين أُنذروا فلم ينتهوا! ففي نجاةِ نوحٍ وإغراقِ قومه سنّةُ الله في نصرِ رسله؛ فاعتبر بعاقبةِ المكذّبين، وأبشر بنجاةِ المؤمنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بنصرِ الله لرسلِه وأتباعِهم، والاعتبارُ بعاقبةِ المكذّبين."},"action":{"text":"أيقن أنّ الله ينجّي المؤمنين ويهلك المكذّبين، فاعتبر بعاقبةِ من أُنذروا فأعرضوا، والزم صفَّ المؤمنين."}}]},{"title":"بعثُ الرسلِ بعد نوح، ومبدأُ قصّةِ موسى مع فرعون","range":[74,78],"theme":"استمرارُ الرسالاتِ، وموقفُ الاستكبارِ من الحقِّ ورميِه بالسحر","verses":[{"n":74,"reflection":{"text":"«ثم بعثنا من بعده رسلا إلى قومهم فجاءوهم بالبينات فما كانوا ليؤمنوا بما كذبوا به من قبل كذلك نطبع على قلوب المعتدين» — ثم بعثنا من بعدِ نوحٍ رسلًا إلى أقوامهم فجاءوهم بالحججِ الواضحة، فما كانوا ليؤمنوا بما سبق أن كذّبوا به أولَ مرّة، فحُرموا التوفيق؛ كذلك نختم على قلوبِ المتجاوزين حدودَ الله المصرّين على الكفر فلا يدخلها الإيمان؛ فالإصرارُ على التكذيبِ يطبع القلب؛ فبادر بالإيمانِ قبل أن يُطبع على قلبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإصرارِ على التكذيبِ الذي يطبع القلب."},"action":{"text":"بادر إلى قبولِ الحقِّ أولَ ما يبلغك، ولا تصرّ على ردّه، فالإصرارُ على التكذيبِ يطبع القلبَ فلا يؤمن."}},{"n":75,"reflection":{"text":"«ثم بعثنا من بعدهم موسى وهارون إلى فرعون وملئه بآياتنا فاستكبروا وكانوا قوما مجرمين» — ثم بعثنا من بعدِ أولئك الرسلِ موسى وأخاه هارون إلى فرعونَ وأشرافِ قومه بآياتنا الدالّةِ على صدقهما، فتكبّروا عن الإيمانِ واتّباعِ الحقّ، وكانوا قومًا مجرمين متجاوزين في الكفرِ والظلم؛ فالكِبرُ حاجبٌ عن الحقّ؛ فاحذر الكبرَ فإنه يصدّ عن الهدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكبرِ الذي يصدّ عن قبولِ الحقّ."},"action":{"text":"احذر الكِبرَ عن الحقّ، فهو الذي منع فرعونَ وملأه من الإيمان، وتواضع لقبولِ الحقِّ ممّن جاء به."}},{"n":76,"reflection":{"text":"«فلما جاءهم الحق من عندنا قالوا إن هذا لسحر مبين» — فلما جاءهم الحقُّ (المعجزاتُ الباهرة) من عندنا على يدِ موسى، لم يجدوا ما يدفعونه به إلا أن قالوا معاندين: إنّ هذا لسحرٌ ظاهر! فوصفوا آياتِ الله البيّناتِ بالسحرِ فرارًا من الإذعان؛ فالمعاندُ يسمّي الحقَّ باطلًا ليردّه؛ فلا تصف الحقَّ بغيرِ اسمه فرارًا من اتّباعه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تسميةُ الأشياءِ بأسمائها، وعدمُ ردِّ الحقِّ بالتلبيس."},"action":{"text":"لا تردّ الحقَّ بوصفه بغيرِ اسمه كما فعل فرعون، بل اقبل الحقَّ إذا تبيّن ولو خالف هواك أو مألوفك."}},{"n":77,"reflection":{"text":"«قال موسى أتقولون للحق لما جاءكم أسحر هذا ولا يفلح الساحرون» — قال موسى منكرًا عليهم: أتصفون الحقَّ لمّا جاءكم بأنه سحر؟ تأمّلوا: أسحرٌ هذا الذي ترون من الآياتِ الباهرة؟ والحالُ أنّ السحرةَ لا يفلحون ولا يغلبون ولا تدوم لهم دولة، فكيف يكون هذا سحرًا وقد ظهر وعلا؟ ففي كلامِ موسى حجّةٌ على أنّ الحقَّ يعلو والسحرَ يزول؛ فميّز الحقَّ بثمرته: الفلاحِ والثبات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تمييزُ الحقِّ عن الباطلِ بثمرتِه وعاقبته."},"action":{"text":"ميّز الحقَّ من الباطلِ بثمرته: فالحقُّ يفلح ويثبت، والسحرُ والباطلُ يزول ولا يفلح صاحبه."}},{"n":78,"reflection":{"text":"«قالوا أجئتنا لتلفتنا عما وجدنا عليه آباءنا وتكون لكما الكبرياء في الأرض وما نحن لكما بمؤمنين» — قال قومُ فرعون لموسى وهارون: أجئتنا لتصرفنا عمّا وجدنا عليه آباءنا من الدينِ والعادة، ولتكون لكما العظمةُ والملكُ في الأرض؟ وما نحن لكما بمصدّقين! فاعتلّوا بتقليدِ الآباءِ وباتّهامِ الرسولِ بطلبِ الدنيا؛ فالتقليدُ الأعمى وسوءُ الظنِّ بالدعاةِ حجابان عن الحقّ؛ فلا يصدّك تقليدُ الآباءِ عن اتّباعِ الدليل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحريرُ القلبِ من تقليدِ الآباءِ الأعمى واتّباعِ الدليل."},"action":{"text":"لا تردّ الحقَّ تعصّبًا لما وجدت عليه آباءك، ولا تسئ الظنَّ بالداعي إلى الله، بل اتّبع الدليلَ حيث كان."}}]},{"title":"مواجهةُ السحرة، وإبطالُ الله للسحر، وإحقاقُ الحق","range":[79,82],"theme":"ثقةُ موسى بنصرِ الله، وأنّ الله يبطل الباطلَ ويحقّ الحق","verses":[{"n":79,"reflection":{"text":"«وقال فرعون ائتوني بكل ساحر عليم» — وقال فرعونُ لمّا عجز عن ردِّ حجّةِ موسى: ائتوني بكلِّ ساحرٍ بارعٍ في السحر ليعارضوا ما جاء به موسى؛ فلجأ إلى السحرِ ليدفع الحقَّ بالباطل؛ فالمبطلُ يجمع أعوانَ الباطلِ ليطفئ نورَ الحقّ، وهو لا يبلغ؛ فلا يخيفنّك تجمّعُ أهلِ الباطل، فالحقُّ غالب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الخوفِ من تجمّعِ أهلِ الباطلِ على إطفاءِ الحق."},"action":{"text":"لا يخيفك اجتماعُ أهلِ الباطلِ وأعوانِهم على الحقّ، فالله مبطلٌ كيدَهم، والحقُّ غالبٌ عليهم."}},{"n":80,"reflection":{"text":"«فلما جاء السحرة قال لهم موسى ألقوا ما أنتم ملقون» — فلما حضر السحرةُ للمبارزة قال لهم موسى واثقًا بربّه: ألقوا ما أنتم ملقون من حبالكم وعصيّكم؛ فلم يهبهم ولا تهيّب جمعهم، لثقته بأنّ الله سيبطل كيدهم؛ ففي جوابِ موسى قوّةُ اليقين؛ فمن وثق بالله لم يهب باطلًا مهما عظُم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قوّةُ اليقينِ بالله تُذهب هيبةَ الباطلِ من القلب."},"action":{"text":"واجه الباطلَ بثقةٍ بالله كما واجه موسى السحرة، فمن وثق بنصرِ الله لم يهب كثرةَ الباطلِ ولا أدواته."}},{"n":81,"reflection":{"text":"«فلما ألقوا قال موسى ما جئتم به السحر إن الله سيبطله إن الله لا يصلح عمل المفسدين» — فلما ألقوا سحرهم قال موسى: الذي جئتم به هو السحرُ (لا ما تصفون به آياتِ الله)، إنّ الله سيبطله ويمحقه، إنّ الله لا يصلح عملَ المفسدين ولا يديمه بل يمحقه؛ فعملُ المفسدِ إلى زوالٍ ومحق؛ فلا تركن إلى باطلٍ فمصيره الاضمحلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يبطل عملَ المفسدين ولا يُديمه."},"action":{"text":"لا تعمل بالباطلِ ولا تركن إليه، فالله لا يصلح عملَ المفسدين بل يبطله، والعاقبةُ للحقِّ وأهله."}},{"n":82,"reflection":{"text":"«ويحق الله الحق بكلماته ولو كره المجرمون» — ويُثبّت الله الحقَّ ويُظهره ويُعليه بكلماته النافذةِ وحججه البالغة، ولو كره ذلك المجرمون المعاندون؛ فسنّةُ الله إحقاقُ الحقِّ وإبطالُ الباطلِ مهما كره الكارهون؛ فاطمئن إلى أنّ الحقَّ منصورٌ بكلماتِ الله وإن كثُر خصومُه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يحق الحق"],"heart_state":{"text":"الطمأنينةُ إلى أنّ الله مُحقٌّ الحقَّ ولو كره المبطلون."},"action":{"text":"اطمئن إلى أنّ الله يُحقّ الحقَّ ويُعليه بكلماته، والزم الحقَّ ولا يهنك كثرةُ من يكرهه من المجرمين."}}]},{"title":"قلّةُ المؤمنين وخوفُهم، وأمرُ التوكّلِ ودعاؤهم","range":[83,86],"theme":"أنّ الحقَّ يُتّبع ولو قلَّ أهلُه، وأنّ التوكّلَ ثمرةُ الإيمان","verses":[{"n":83,"reflection":{"text":"«فما آمن لموسى إلا ذرية من قومه على خوف من فرعون وملئهم أن يفتنهم وإن فرعون لعال في الأرض وإنه لمن المسرفين» — فما آمن لموسى في أوّلِ أمره إلا قليلٌ من شبابِ قومه (بني إسرائيل)، على خوفٍ من فرعونَ وأشرافِ قومه أن يعذّبوهم ويصدّوهم عن دينهم؛ وإنّ فرعونَ لمتكبّرٌ متسلّطٌ في الأرض، وإنه لمن المتجاوزين الحدَّ في الظلمِ والكفر؛ ففي إيمانِ القلّةِ مع الخوفِ صدقٌ وثبات؛ فاثبت على الحقِّ ولو كان أهلُه قلّةً خائفين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ ولو قلَّ أهلُه واشتدّ الخوف."},"action":{"text":"اثبت على الحقِّ ولو كنت في قلّةٍ يخافون، فالعبرةُ بصدقِ الإيمانِ لا بكثرةِ العدد، والعاقبةُ للمتقين."}},{"n":84,"reflection":{"text":"«وقال موسى يا قوم إن كنتم آمنتم بالله فعليه توكلوا إن كنتم مسلمين» — وقال موسى لقومه المؤمنين: يا قوم إن كنتم صدّقتم بالله حقًّا فاعتمدوا عليه وحده في دفعِ عدوّكم، إن كنتم منقادين لأمره مستسلمين له؛ ففي كلامه أنّ التوكّلَ ثمرةُ الإيمانِ الصادقِ والإسلام؛ فحقّق إيمانك بالتوكّلِ على الله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ التوكّلَ على الله ثمرةُ الإيمانِ والإسلام."},"action":{"text":"توكّل على الله وحده في كلِّ أمرك، فذاك مقتضى إيمانك وإسلامك، ولا تعتمد على قوّتك أو غيرك دونه."}},{"n":85,"reflection":{"text":"«فقالوا على الله توكلنا ربنا لا تجعلنا فتنة للقوم الظالمين» — فاستجاب المؤمنون وقالوا: على الله وحده اعتمدنا، ربّنا لا تسلّط علينا الظالمين فيفتنونا عن ديننا أو يظنّوا أنهم على حقٍّ فيزدادوا طغيانًا؛ ففي دعائهم توكّلٌ وافتقار؛ فادعُ الله ألّا يجعلك فتنةً لأهلِ الباطل، معتمدًا عليه وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوكّلُ المقرونُ بالدعاءِ والافتقارِ إلى الله."},"action":{"text":"توكّل على الله وادعه أن يحفظك من فتنةِ الظالمين وتسلّطهم، فاجمع بين الاعتمادِ عليه والتضرّعِ إليه."}},{"n":86,"reflection":{"text":"«ونجنا برحمتك من القوم الكافرين» — وأتمّوا دعاءهم: ونجّنا يا ربّنا برحمتك من أذى القومِ الكافرين وسلطانهم؛ فسألوا النجاةَ برحمةِ الله لا بحولهم؛ ففي تعليقِ النجاةِ برحمةِ الله لا بالعملِ محضُ الافتقار؛ فاطلب النجاةَ برحمةِ الله لا بحولك، معلّقًا رجاءك بفضله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الرحمة"],"heart_state":{"text":"طلبُ النجاةِ برحمةِ الله لا بالحولِ والقوّة."},"action":{"text":"اسأل الله النجاةَ من كلِّ شرٍّ برحمته لا بحولك، وعلّق رجاءك بفضله ورحمته لا بعملك وقوّتك."}}]},{"title":"اتّخاذُ البيوتِ مساجد، ودعاءُ موسى، وإجابةُ الله","range":[87,89],"theme":"الاستعانةُ بالصلاةِ في الشدّة، ودعاءُ النبيِّ على المعاندين واستجابتُه","verses":[{"n":87,"reflection":{"text":"«وأوحينا إلى موسى وأخيه أن تبوآ لقومكما بمصر بيوتا واجعلوا بيوتكم قبلة وأقيموا الصلاة وبشر المؤمنين» — وأوحينا إلى موسى وأخيه هارون أن اتّخذا لقومكما بمصرَ بيوتًا يأوون إليها ويتعبّدون فيها آمنين، واجعلوا بيوتكم مساجدَ متوجّهةً للقبلة، وأقيموا الصلاةَ فيها (لمّا مُنعوا من إظهارِ دينهم)، وبشّر المؤمنين بالنصرِ والفرج؛ ففي الصلاةِ عونٌ وثباتٌ وقتَ الشدّة؛ فالجأ إلى الصلاةِ في ضيقك، فهي ملاذُ المؤمنِ وسلاحُه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الصلاةِ وقتَ الشدّةِ استعانةً وثباتًا."},"action":{"text":"الجأ إلى الصلاةِ في شدّتك وضيقك كما أُمر بنو إسرائيل، فبها يثبت القلبُ ويأتي الفرج، وبشّر نفسك بالنصر."}},{"n":88,"reflection":{"text":"«وقال موسى ربنا إنك آتيت فرعون وملأه زينة وأموالا في الحياة الدنيا ربنا ليضلوا عن سبيلك ربنا اطمس على أموالهم واشدد على قلوبهم فلا يؤمنوا حتى يروا العذاب الأليم» — وقال موسى داعيًا بعد أن يئس من إيمانهم: ربّنا إنك أعطيت فرعونَ وأشرافَه زينةً وأموالًا في الدنيا فاتّخذوها وسيلةً للإضلالِ عن سبيلك؛ ربّنا أهلك أموالهم واطبع على قلوبهم فلا يؤمنوا حتى يعاينوا العذابَ الأليم؛ فدعا عليهم لمّا علم إصرارهم وفسادهم؛ ففي هذا أنّ النعمةَ على الظالمِ قد تكون استدراجًا؛ فلا تغترّ بنعمةٍ سُخّرت للإضلال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ألّا يغترَّ القلبُ بالنعمةِ إذا صُرفت في الإضلالِ والباطل."},"action":{"text":"لا تغترّ بنعمةٍ سُخّرت في معصيةٍ وإضلال، واستعمل ما آتاك الله في طاعته وسبيله لا في صدِّ الناسِ عنه."}},{"n":89,"reflection":{"text":"«قال قد أجيبت دعوتكما فاستقيما ولا تتبعان سبيل الذين لا يعلمون» — قال الله: قد أُجيبت دعوةُ موسى وهارون (والتأمينُ من هارون دعاء)، فاستقيما على دينكما وأمري ودعوتكما ولا تستعجلا، ولا تسلكا سبيلَ الجاهلين الذين لا يعلمون حكمةَ الله في تأخيرِ العقوبة؛ ففي هذا أنّ إجابةَ الدعاءِ قد تتأخّر لحكمة، وأنّ الاستقامةَ مطلوبةٌ بعد الدعاء؛ فبعد دعائك الزم الاستقامةَ ولا تستعجل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستقامةُ بعد الدعاءِ، وعدمُ استعجالِ الإجابة."},"action":{"text":"ادعُ الله ثم الزم الاستقامةَ على أمره ولا تستعجل الإجابة، فقد تتأخّر لحكمة، ولا تتّبع سبيلَ الجاهلين."}}]},{"title":"إغراقُ فرعون، وإيمانُه حين لا ينفع، ونجاةُ بدنه آية","range":[90,92],"theme":"عاقبةُ الطغيان، وأنّ توبةَ الغرغرةِ لا تُقبل، وجعلُ بدنِ فرعونَ عبرة","verses":[{"n":90,"reflection":{"text":"«وجاوزنا ببني إسرائيل البحر فأتبعهم فرعون وجنوده بغيا وعدوا حتى إذا أدركه الغرق قال آمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل وأنا من المسلمين» — وعبرنا ببني إسرائيلَ البحرَ (بعد أن فلقناه)، فتبعهم فرعونُ وجنودُه ظلمًا وعدوانًا، حتى إذا أحاط به الغرقُ ويئس، قال: آمنتُ أنه لا إله إلا الذي آمنت به بنو إسرائيل وأنا من المستسلمين؛ فلمّا عاين الهلاكَ آمن حين لا ينفع الإيمان؛ فالتوبةُ عند معاينةِ الموتِ لا تُقبل؛ فبادر بالإيمانِ في زمنِ المهلة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ قبل معاينةِ الموتِ حيث لا ينفع."},"action":{"text":"آمن وتب في صحّتك ومهلتك، فإيمانُ فرعونَ عند الغرقِ لم ينفعه، وتوبةُ الغرغرةِ لا تُقبل."}},{"n":91,"reflection":{"text":"«آلآن وقد عصيت قبل وكنت من المفسدين» — قيل لفرعونَ توبيخًا: آلآن تؤمن وقد عصيت الله قبل ذلك طولَ عمرك، وكنت من المفسدين في الأرضِ الصادّين عن سبيل الله؟ فإيمانُك الآن لا يُقبل؛ ففي هذا أنّ من أمضى عمرَه في العصيانِ ثم أراد التوبةَ عند الموتِ فقد فات الأوان؛ فلا تسوّف التوبةَ إلى ساعةِ الاحتضار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تسويفِ التوبةِ إلى ساعةِ فواتها."},"action":{"text":"لا تسوّف التوبةَ حتى يحضرك الموت، فتوبةُ فرعونَ ردّت لتأخّرها، فبادر بها ما دمت في مهلةِ العمل."}},{"n":92,"reflection":{"text":"«فاليوم ننجيك ببدنك لتكون لمن خلفك آية وإن كثيرا من الناس عن آياتنا لغافلون» — فاليوم نُخرج بدنك من البحرِ سالمًا على نجوةٍ من الأرضِ ليراه الناسُ، لتكون لمن بعدك عبرةً وآيةً على أنّ الجبّارَ قد يهلك ويصير عبرة؛ وإنّ كثيرًا من الناسِ عن آياتِ الله وعبره لغافلون لا يتّعظون؛ ففي مصرعِ فرعونَ عبرةٌ لكلِّ طاغٍ؛ فاعتبر بمصارعِ الطغاةِ ولا تكن من الغافلين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الطغاةِ وعدمُ الغفلةِ عن آياتِ الله."},"action":{"text":"اعتبر بمصيرِ فرعونَ الذي صار بدنُه آيةً للمعتبرين، ولا تكن من الغافلين عن آياتِ الله وعبره."}}]},{"title":"تبوئةُ بني إسرائيلَ وابتلاؤهم بالاختلاف","range":[93,93],"theme":"أنّ النعمةَ لا تعصم من الاختلافِ إذا فُقد الإخلاص، وأنّ الله يفصل يوم القيامة","verses":[{"n":93,"reflection":{"text":"«ولقد بوأنا بني إسرائيل مبوأ صدق ورزقناهم من الطيبات فما اختلفوا حتى جاءهم العلم إن ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون» — ولقد أنزلنا بني إسرائيلَ منزلًا حسنًا كريمًا (الشامَ ومصرَ بعد هلاكِ عدوّهم)، ورزقناهم من طيّباتِ الرزق، فما اختلفوا في دينهم وتفرّقوا حتى جاءهم العلمُ (بمحمدٍ ﷺ أو بما في كتبهم)، فكان اختلافُهم بغيًا وحسدًا بعد قيامِ الحجّة؛ إنّ ربّك يقضي بينهم يوم القيامةِ فيما اختلفوا فيه؛ ففي هذا أنّ الاختلافَ بعد العلمِ مذموم؛ فاجعل العلمَ سببًا للاجتماعِ على الحقِّ لا للفرقة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ العلمَ يُوجب الاجتماعَ على الحقِّ لا التفرّقَ بغيًا."},"action":{"text":"اجعل علمك سببًا لاجتماعك على الحقِّ لا للاختلافِ بغيًا وحسدًا، فذمُّ الله للمختلفين بعد قيامِ الحجّة."}}]},{"title":"ثباتُ الحقِّ الذي جاء به الوحي، والنهيُ عن الامتراء","range":[94,95],"theme":"تثبيتُ اليقينِ بالوحيِ، والتحذيرُ من الشكِّ والتكذيب","verses":[{"n":94,"reflection":{"text":"«فإن كنت في شك مما أنزلنا إليك فاسأل الذين يقرءون الكتاب من قبلك لقد جاءك الحق من ربك فلا تكونن من الممترين» — الخطابُ للنبيِّ ﷺ والمرادُ أمّته أو تثبيتُه: فإن حصل شكٌّ (فرضًا) فيما أنزلنا إليك فاسأل مؤمني أهلِ الكتابِ الذين يقرؤون التوراةَ والإنجيل فسيشهدون بصدقِ ما جاءك موافقًا لما عندهم؛ لقد جاءك الحقُّ اليقينُ من ربّك فلا تكوننّ من الشاكّين المرتابين؛ ففي هذا تثبيتُ اليقين؛ فاطرح الشكَّ عن قلبك، فالحقُّ قد جاءك من ربّك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طرحُ الشكِّ والثباتُ على يقينِ الوحي."},"action":{"text":"اطرح الشكَّ عن قلبك في الحقّ، فقد جاءك اليقينُ من ربّك، والزم اليقينَ ولا تكن من المرتابين."}},{"n":95,"reflection":{"text":"«ولا تكونن من الذين كذبوا بآيات الله فتكون من الخاسرين» — ولا تكوننّ من الذين كذّبوا بآياتِ الله وحججه فتكون من الخاسرين لدينهم ودنياهم وآخرتهم؛ ففي هذا غايةُ التحذيرِ من التكذيبِ بشيءٍ من آياتِ الله؛ فاحذر أن تكذّب بشيءٍ من الحقِّ فتخسر، وصدّق بكلِّ ما جاء عن الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ الشديدُ من التكذيبِ بشيءٍ من آياتِ الله."},"action":{"text":"صدّق بكلِّ ما جاء عن الله من آياته، واحذر أن تكذّب بشيءٍ منها فتكون من الخاسرين."}}]},{"title":"من حقّت عليهم الكلمةُ لا يؤمنون","range":[96,97],"theme":"أنّ المصرّين على الكفرِ لا تنفعهم الآياتُ حتى يعاينوا العذاب","verses":[{"n":96,"reflection":{"text":"«إن الذين حقت عليهم كلمت ربك لا يؤمنون» — إنّ الذين وجب عليهم قضاءُ الله بالشقاءِ لإصرارهم واختيارهم الكفرَ لا يؤمنون، لأنهم أغلقوا على أنفسهم بابَ الهدى بعنادهم؛ ففي هذا أنّ من طبع الله على قلبه بكسبه لا يؤمن؛ فاحذر أسبابَ الطبعِ على القلب، وتعرّض لأسبابِ الهداية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أسبابِ الطبعِ على القلبِ بالعنادِ والإصرار."},"action":{"text":"احذر العنادَ والإصرارَ على المعصية، فهما يُوجبان الطبعَ على القلب، وتعرّض دائمًا لأسبابِ الهداية."}},{"n":97,"reflection":{"text":"«ولو جاءتهم كل آية حتى يروا العذاب الأليم» — ولو جاءت هؤلاء المعاندين كلُّ آيةٍ وحجّةٍ لما آمنوا، حتى يعاينوا العذابَ الأليمَ حين لا ينفع الإيمان؛ فالعنادُ يُعمي عن كلِّ برهان؛ ففي هذا أنّ الآياتِ لا تنفع مع سبقِ الشقاءِ والعناد؛ فاطلب الهدايةَ بقلبٍ منقادٍ لا معاند، فالبرهانُ لا يهدي القلبَ المعاند.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الهدايةَ بانقيادِ القلبِ لا بكثرةِ البراهينِ مع العناد."},"action":{"text":"اطلب الهدى بقلبٍ منقادٍ للحقّ، فالبراهينُ لا تنفع القلبَ المعاند، ولا تجعل عنادك حاجبًا عن الحقّ."}}]},{"title":"قومُ يونسَ — إيمانٌ نافعٌ رفع العذاب","range":[98,98],"theme":"أنّ التوبةَ قبل نزولِ العذابِ تنفع، وتفرّدُ قومِ يونسَ بالإيمانِ الجماعيّ النافع","verses":[{"n":98,"reflection":{"text":"«فلولا كانت قرية آمنت فنفعها إيمانها إلا قوم يونس لما آمنوا كشفنا عنهم عذاب الخزي في الحياة الدنيا ومتعناهم إلى حين» — فهلّا وُجدت قريةٌ من القرى المهلكةِ آمنت قبل نزولِ العذابِ فنفعها إيمانها؟ ما حدث ذلك إلا في قومِ يونسَ، فإنهم لمّا رأوا مقدّماتِ العذابِ آمنوا جميعًا وتابوا صادقين قبل حلوله، فكشفنا عنهم عذابَ الذلِّ في الدنيا ومتّعناهم إلى انقضاءِ آجالهم؛ ففي قومِ يونسَ (الذين سُمّيت بهم السورة) عبرةٌ: أنّ التوبةَ الصادقةَ الجماعيّةَ قبل معاينةِ العذابِ ترفع البلاء؛ فبادر بالتوبةِ قبل حلولِ العقوبة، فباب الله مفتوح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["قوم يونس"],"heart_state":{"text":"الرجاءُ في أنّ التوبةَ الصادقةَ قبل العذابِ ترفع البلاء."},"action":{"text":"بادر بالتوبةِ الصادقةِ قبل نزولِ العقوبة كما فعل قومُ يونس، فرفع الله عنهم العذاب، فبابُ التوبةِ مفتوحٌ لمن أناب."}}]},{"title":"الهدايةُ بمشيئةِ الله، ولا إكراهَ في الدين","range":[99,100],"theme":"أنّ الإيمانَ لا يكون بالإكراهِ بل بإذنِ الله وتوفيقه","verses":[{"n":99,"reflection":{"text":"«ولو شاء ربك لآمن من في الأرض كلهم جميعا أفأنت تكره الناس حتى يكونوا مؤمنين» — ولو شاء ربّك إيمانَ أهلِ الأرضِ كلِّهم لآمنوا جميعًا، ولكنه اقتضت حكمتُه أن يؤمن قومٌ ويكفر قوم ابتلاءً؛ أفأنت يا محمد تقدر أن تُكره الناسَ على الإيمانِ قسرًا حتى يصيروا مؤمنين؟ لا سبيلَ إلى ذلك، فالهدايةُ بيدِ الله؛ ففي هذا تخفيفٌ عن النبيِّ وأنّ الدينَ لا يُدخَل بالإكراه؛ فابذل الدعوةَ ولا تحمل همَّ ما ليس إليك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفويضُ الهدايةِ إلى الله، وطرحُ همِّ ما ليس للعبد."},"action":{"text":"ابذل الدعوةَ إلى الحقِّ بصدق، ولا تحمل همَّ إكراهِ الناسِ على الهدى، فالهدايةُ بيدِ الله وحده يهدي من يشاء."}},{"n":100,"reflection":{"text":"«وما كان لنفس أن تؤمن إلا بإذن الله ويجعل الرجس على الذين لا يعقلون» — وما كان لأحدٍ أن يؤمن إلا بإذنِ الله وتوفيقه ومشيئته، فالإيمانُ بيده لا بيدِ العبدِ وحده؛ ويجعل الرجسَ (العذابَ أو الخذلانَ والكفر) على الذين لا يعقلون عن الله حججَه ولا يتدبّرونها؛ ففي هذا أنّ إعمالَ العقلِ في آياتِ الله بابُ الإيمان، وتعطيلَه بابُ الرجس؛ فأعمل عقلك في آياتِ الله تُوفَّق للإيمان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ التوفيقِ للإيمانِ من الله، وإعمالُ العقلِ في آياته."},"action":{"text":"اسأل الله التوفيقَ للإيمان فهو بإذنه، وأعمل عقلك في آياته وتدبّرها، فتعطيلُ العقلِ عن الحقِّ بابُ الخذلان."}}]},{"title":"النظرُ في آياتِ الكون، وانتظارُ سنّةِ الله، ونجاةُ المؤمنين","range":[101,103],"theme":"دعوةُ التأمّلِ في الكون، وأنّ سنّةَ الله نجاةُ رسلِه وأهلِ الإيمان","verses":[{"n":101,"reflection":{"text":"«قل انظروا ماذا في السماوات والأرض وما تغني الآيات والنذر عن قوم لا يؤمنون» — قل يا محمد للناس: تأمّلوا بعقولكم ما في السماواتِ والأرضِ من عجائبِ الخلقِ الدالّةِ على وحدانيّةِ الله وقدرته؛ لكنّ هذه الآياتِ والرسلَ المنذرين لا تنفع قومًا سبق في علمِ الله أنهم لا يؤمنون لإعراضهم؛ ففي هذا حثٌّ على التأمّلِ في الكون، وأنّ النفعَ لمن فتح قلبه؛ فأدم النظرَ في خلقِ الله بقلبٍ مؤمنٍ ينتفع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في آياتِ الكونِ بقلبٍ مؤمنٍ يزداد يقينًا."},"action":{"text":"أدِم النظرَ والتأمّلَ في السماواتِ والأرضِ وعجائبِ خلقِ الله، بقلبٍ مؤمنٍ ينتفع، فيزداد يقينك وإيمانك."}},{"n":102,"reflection":{"text":"«فهل ينتظرون إلا مثل أيام الذين خلوا من قبلهم قل فانتظروا إني معكم من المنتظرين» — فهل ينتظر هؤلاء المكذّبون إلا وقائعَ كوقائعِ الأممِ الهالكةِ قبلهم من العذابِ والنكال؟ قل لهم: فانتظروا نزولَ ما تستحقّون، إني معكم من المنتظرين لنصرِ الله ووعده؛ ففي هذا تهديدٌ بأنّ سنّةَ الله في المكذّبين واحدة؛ فاحذر أن تسلك سبيلَ من هلك، فتنالك سنّةُ الله فيهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بسنّةِ الله في المكذّبين، والحذرُ من سلوكِ سبيلهم."},"action":{"text":"احذر أن تكذّب فتنالك سنّةُ الله في المكذّبين قبلك، واعتبر بأيّامهم، وانتظر نصرَ الله إن كنت من أهلِ الحقّ."}},{"n":103,"reflection":{"text":"«ثم ننجي رسلنا والذين آمنوا كذلك حقا علينا ننج المؤمنين» — ثم ننجّي رسلنا والذين آمنوا معهم من العذابِ الذي يحلُّ بالمكذّبين؛ كذلك أوجبنا على أنفسنا فضلًا ورحمةً أن ننجّيَ المؤمنين؛ ففي هذا وعدٌ كريمٌ بنجاةِ المؤمنين، وأنها حقٌّ أوجبه الله على نفسه؛ فأبشر بأنّ الله ينجّي المؤمنين، فالزم الإيمانَ والعملَ تكن من الناجين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ننج المؤمنين"],"heart_state":{"text":"الرجاءُ في وعدِ الله بنجاةِ المؤمنين وضمانِه لها."},"action":{"text":"الزم الإيمانَ الصادقَ والعملَ الصالح، وأبشر بأنّ الله أوجب على نفسه نجاةَ المؤمنين، فكن منهم."}}]},{"title":"إعلانُ التوحيدِ، وإقامةُ الوجهِ للدين، ونفعُ الله وضرُّه","range":[104,107],"theme":"البراءةُ من الشرك، والاستقامةُ على الدينِ الحنيف، وتفرّدُ الله بالضرِّ والنفع","verses":[{"n":104,"reflection":{"text":"«قل يا أيها الناس إن كنتم في شك من ديني فلا أعبد الذين تعبدون من دون الله ولكن أعبد الله الذي يتوفاكم وأمرت أن أكون من المؤمنين» — قل يا محمد: يا أيها الناسُ إن كنتم في شكٍّ من صحّةِ ديني الذي أدعو إليه، فاعلموا أني على يقينٍ منه: لا أعبد آلهتكم التي تعبدونها من دون الله، ولكن أعبد الله وحده الذي يتوفّاكم فبيده حياتُكم وموتكم، وأُمرت أن أكون من المؤمنين؛ ففي هذا إعلانُ التوحيدِ والبراءةِ من الشركِ على يقين؛ فأعلن توحيدك واثبت عليه بلا شكّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على التوحيدِ بيقينٍ والبراءةُ من الشرك."},"action":{"text":"أعلن توحيدك لله وحده واثبت عليه بيقينٍ لا شكَّ فيه، وابرأ من عبادةِ كلِّ ما سواه، فبيده حياتك وموتك."}},{"n":105,"reflection":{"text":"«وأن أقم وجهك للدين حنيفا ولا تكونن من المشركين» — وأُمرت أن أقيم وجهي وقصدي للدينِ القيّمِ مائلًا عن كلِّ دينٍ باطلٍ إلى التوحيدِ الخالص (الحنيفيّة)، ولا أكون من المشركين بالله شيئًا؛ ففي هذا الأمرُ بالإخلاصِ والاستقامةِ على ملّةِ التوحيد؛ فأقبل بقلبك وعملك على دينِ الله خالصًا، مائلًا عن كلِّ باطل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الوجهةِ لله والاستقامةُ على التوحيدِ الحنيف."},"action":{"text":"أقبل بقلبك وعملك على دينِ الله خالصًا حنيفًا، معرضًا عن كلِّ باطل، ولا تخلط توحيدك بشائبةِ شرك."}},{"n":106,"reflection":{"text":"«ولا تدع من دون الله ما لا ينفعك ولا يضرك فإن فعلت فإنك إذا من الظالمين» — ولا تعبد ولا تدعُ من دون الله آلهةً لا تقدر أن تنفعك إن دعوتها ولا تضرّك إن تركتها، فإن فعلت ذلك فإنك حينئذٍ من الظالمين لأنفسهم بالشركِ الذي هو أعظمُ الظلم؛ ففي هذا أنّ دعاءَ غيرِ الله ظلمٌ وسفه؛ فلا تدعُ إلا الله، فدعاءُ العاجزِ عن نفعك وضرّك عينُ الظلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالدعاء، وأنّ دعاءَ غيرِه ظلمٌ للنفس."},"action":{"text":"لا تدعُ ولا ترجُ إلا الله، ولا تعلّق قلبك بما لا يملك نفعًا ولا ضرًّا، فدعاءُ غيرِ الله ظلمٌ عظيم."}},{"n":107,"reflection":{"text":"«وإن يمسسك الله بضر فلا كاشف له إلا هو وإن يردك بخير فلا راد لفضله يصيب به من يشاء من عباده وهو الغفور الرحيم» — وإن يصبك الله بشدّةٍ أو بلاءٍ فلا أحدَ يقدر على كشفه ورفعه إلا هو، وإن يُردك بخيرٍ ونعمةٍ فلا أحدَ يقدر على ردِّ فضله ومنعه، يصيب بفضله من يشاء من عباده، وهو الغفورُ لذنوبِ التائبين الرحيمُ بهم؛ ففي هذا حصرُ النفعِ والضرِّ بيدِ الله وحده؛ فعلّق قلبك بالله وحده، فلا كاشفَ لضرّك ولا رادَّ لفضله سواه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"تعلّقُ القلبِ بالله وحده، إذ لا كاشفَ للضرِّ ولا مانعَ للخيرِ سواه."},"action":{"text":"علّق رجاءك وخوفك بالله وحده، فلا يكشف ضرَّك إلا هو ولا يردّ فضلَه أحد، والجأ إليه فهو الغفورُ الرحيم."}}]},{"title":"مجيءُ الحقِّ، واتّباعُ الوحيِ والصبرُ حتى حكمِ الله","range":[108,109],"theme":"أنّ ثمرةَ الهدى للمهتدي، وختمُ السورةِ بأمرِ الاتّباعِ والصبر","verses":[{"n":108,"reflection":{"text":"«قل يا أيها الناس قد جاءكم الحق من ربكم فمن اهتدى فإنما يهتدي لنفسه ومن ضل فإنما يضل عليها وما أنا عليكم بوكيل» — قل يا محمد: يا أيها الناسُ قد جاءكم الحقُّ (القرآنُ والدينُ) من ربّكم لا شكَّ فيه، فمن اهتدى به فإنما ثمرةُ هدايته لنفسه، ومن ضلّ عنه فإنما وبالُ ضلاله على نفسه، وما أنا عليكم بحفيظٍ موكَّلٍ بأعمالكم، إنما أنا مبلّغ؛ ففي هذا أنّ نفعَ الهدى وضرَّ الضلالِ عائدٌ على العبد؛ فاهتدِ بالحقِّ فنفعُه لك، ولا تنتظر من يحملك عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ إلى الاهتداءِ بالحقِّ إذ نفعُه للمهتدي نفسِه."},"action":{"text":"بادر إلى الاهتداءِ بالحقِّ الذي جاءك، فثمرةُ هدايتك لك وحدك، ووبالُ الضلالِ عليك، فاختر لنفسك النجاة."}},{"n":109,"reflection":{"text":"«واتبع ما يوحى إليك واصبر حتى يحكم الله وهو خير الحاكمين» — واتّبع يا محمد ما يُوحى إليك من ربّك قولًا وعملًا ودعوةً، ولا تلتفت إلى ما سواه، واصبر على أذى المكذّبين وعلى مشقّةِ التبليغِ حتى يحكم الله بينك وبينهم بالنصرِ في الدنيا والفصلِ في الآخرة، وهو خيرُ الحاكمين وأعدلُهم؛ فخُتمت السورةُ بجماعِ أمرِ الداعية: اتّباعُ الوحيِ والصبرُ على طريقه؛ فالزم الوحيَ واصبر على طاعةِ الله حتى يأتيَ حكمُه، فهو خيرُ الحاكمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["خير الحاكمين"],"heart_state":{"text":"لزومُ اتّباعِ الوحيِ والصبرُ على الحقِّ حتى يحكم الله."},"action":{"text":"اتّبع ما جاءك عن الله واعمل به، واصبر على مشقّةِ الطاعةِ وأذى المخالفين حتى يحكم الله، فهو خيرُ الحاكمين."}}]}],"coverage":{"covered":109,"total":109}};
